428	            continue;
429	        }
430	
431	        for m in g.package_members().cloned().collect::<Vec<_>>() {
432	            let cur = agg.severities.get(&m).copied().unwrap_or(Severity::None);
433	            if target > cur {
434	                // Guard against stale group members: a package listed in the
435	                // config group that was subsequently removed from the workspace
436	                // must not be inserted into severities.  Doing so causes
437	                // `bump_target` in `solve_cascade` to call
438	                // `input.base.get(stale_id)` -> `None` ->
439	                // `Err(GraphError::Manifest(MissingField))`, which surfaces as
440	                // a misleading crash.  Emit a warning instead and skip.
441	                if !base_versions.contains_key(&m) {
442	                    agg.diagnostics.push(Diagnostic {
