292	/// One physical write of a version plan, in the order it must happen.
293	enum WriteStep<'p> {
294	    /// One load/mutate/persist cycle over a manifest only the `Manifest` trait writes: the
295	    /// version bump (idempotency-guarded) first, then every dependency rewrite, one persist.
296	    Manifest {
297	        path: &'p PathBuf,
298	        group: &'p ManifestWriteGroup,
299	    },
300	    /// The same cycle for a Cargo workspace root only the `WorkspaceCargoResolver` writes. Its
301	    /// writes carry no idempotency precondition.
302	    WorkspaceRoot {
303	        root_manifest: &'p PathBuf,
304	        group: &'p ManifestWriteGroup,
305	    },
306	    /// Mixed-routing manifests (written through both routes) are never batched: each write is
307	    /// its own load/persist, strictly in plan order.
308	    MixedManifestVersion {
309	        path: &'p PathBuf,
310	        bump: &'p PlannedBump,
311	    },
312	    MixedWorkspaceVersion {
313	        root_manifest: &'p PathBuf,
314	        to: &'p Version,
315	    },
316	    MixedManifestRewrite {
317	        path: &'p PathBuf,
318	        rewrite: &'p SpecRewrite,
319	    },
320	    MixedWorkspaceRewrite {
321	        root_manifest: &'p PathBuf,
322	        rewrite: &'p SpecRewrite,
323	    },
324	    PlatformVersion(&'p PlatformWrite),
325	    OptionalDependencies(&'p OptionalDepUpdate),
326	}
327	
328	/// Orders every manifest write once, so execution is a single `match` and the per-file order
329	/// (bump, then rewrites, then one persist) is data rather than control flow.
330	fn write_steps<'p>(plan: &'p VersionPlan, classification: &'p ManifestWriteClassification) -> Vec<WriteStep<'p>> {
331	    let mut steps = Vec::new();
332	    for (path, group) in &classification.batched {
333	        steps.push(WriteStep::Manifest { path, group });
334	    }
335	    for (root_manifest, group) in &classification.resolver_batched {
336	        steps.push(WriteStep::WorkspaceRoot { root_manifest, group });
337	    }
338	    for bump in &plan.bumps {
339	        for write in &bump.writes {
340	            match write {
341	                VersionWriteTarget::Manifest(path) if classification.excluded.contains(path) => {
342	                    steps.push(WriteStep::MixedManifestVersion { path, bump });
343	                }
344	                VersionWriteTarget::CargoWorkspacePackage { root_manifest }
345	                    if !classification.resolver_batched.contains_key(root_manifest) =>
346	                {
347	                    steps.push(WriteStep::MixedWorkspaceVersion {
348	                        root_manifest,
349	                        to: &bump.to,
350	                    });
351	                }
352	                _ => {}
353	            }
354	        }
355	    }
356	    for rewrite in &plan.rewrites {
357	        match &rewrite.key.target {
358	            DepWriteTarget::Manifest(path) if classification.excluded.contains(path) => {
359	                steps.push(WriteStep::MixedManifestRewrite { path, rewrite });
360	            }
361	            DepWriteTarget::CargoWorkspaceDependency { root_manifest }
362	                if !classification.resolver_batched.contains_key(root_manifest) =>
363	            {
364	                steps.push(WriteStep::MixedWorkspaceRewrite { root_manifest, rewrite });
365	            }
366	            _ => {}
367	        }
368	    }
369	    steps.extend(plan.platform_writes.iter().map(WriteStep::PlatformVersion));
370	    steps.extend(plan.optional_dep_updates.iter().map(WriteStep::OptionalDependencies));
371	    steps
372	}
373	
374	/// Performs one step and returns the path to stage.
375	fn apply_write_step(
376	    step: &WriteStep<'_>,
377	    plan: &VersionPlan,
378	    root: &Path,
379	    ctx: &OpenContext<'_>,
380	    permit: &ApplyPermit,
381	) -> Result<PathBuf, GraphError> {
382	    match step {
383	        WriteStep::Manifest { path, group } => {
384	            let mut handle = open_canonical(path, ctx)?;
385	            let mut mutated = false;
386	            if let Some((bump_idx, target_version)) = &group.bump {
387	                let bump = &plan.bumps[*bump_idx];
388	                mutated = write_version_guarded(handle.as_mut(), path, &bump.from, target_version, permit)?;
389	            }
390	            for rewrite_idx in &group.rewrite_indices {
391	                rewrite_dependency(handle.as_mut(), &plan.rewrites[*rewrite_idx], permit)?;
392	                mutated = true;
393	            }
394	            if mutated {
395	                handle.persist(permit)?;
396	            }
397	            Ok((*path).clone())
398	        }
399	        WriteStep::WorkspaceRoot { root_manifest, group } => {
400	            let mut ws_res = WorkspaceCargoResolver::load_at(root, root_manifest)?;
401	            let mut mutated = false;
402	            if let Some((_, target_version)) = &group.bump {
403	                ws_res.write_version(target_version, permit)?;
404	                mutated = true;
405	            }
406	            for rewrite_idx in &group.rewrite_indices {
407	                let rewrite = &plan.rewrites[*rewrite_idx];
408	                ws_res.write_dependency(&rewrite.key.name, rewrite.to.clone(), permit)?;
409	                mutated = true;
410	            }
411	            if mutated {
412	                ws_res.persist(permit)?;
413	            }
414	            Ok((*root_manifest).clone())
415	        }
416	        WriteStep::MixedManifestVersion { path, bump } => {
417	            let mut handle = open_canonical(path, ctx)?;
418	            if write_version_guarded(handle.as_mut(), path, &bump.from, &bump.to, permit)? {
419	                handle.persist(permit)?;
420	            }
421	            Ok((*path).clone())
422	        }
423	        WriteStep::MixedWorkspaceVersion { root_manifest, to } => {
424	            let mut ws_res = WorkspaceCargoResolver::load_at(root, root_manifest)?;
425	            ws_res.write_version(to, permit)?;
426	            ws_res.persist(permit)?;
427	            Ok((*root_manifest).clone())
428	        }
429	        WriteStep::MixedManifestRewrite { path, rewrite } => {
430	            let mut handle = open_canonical(path, ctx)?;
431	            rewrite_dependency(handle.as_mut(), rewrite, permit)?;
432	            handle.persist(permit)?;
433	            Ok((*path).clone())
434	        }
435	        WriteStep::MixedWorkspaceRewrite { root_manifest, rewrite } => {
436	            let mut ws_res = WorkspaceCargoResolver::load_at(root, root_manifest)?;
437	            ws_res.write_dependency(&rewrite.key.name, rewrite.to.clone(), permit)?;
438	            ws_res.persist(permit)?;
439	            Ok((*root_manifest).clone())
440	        }
441	        WriteStep::PlatformVersion(write) => {
442	            let mut handle = open_canonical(&write.manifest, ctx)?;
443	            if write_version_guarded(handle.as_mut(), &write.manifest, &write.from, &write.version, permit)? {
444	                handle.persist(permit)?;
445	            }
446	            Ok(write.manifest.clone())
447	        }
448	        WriteStep::OptionalDependencies(update) => {
449	            let mut handle = open_canonical(&update.manifest, ctx)?;
450	            handle.update_optional_dependencies(&update.updates, permit)?;
451	            handle.persist(permit)?;
452	            Ok(update.manifest.clone())
453	        }
454	    }
455	}
456	
457	fn open_canonical(path: &Path, ctx: &OpenContext<'_>) -> Result<Box<dyn Manifest>, GraphError> {
458	    let fmt = callisto_model::ManifestFormat::from_path(path)?;
459	    let decl = callisto_model::ManifestDecl::new(path, ManifestRole::Canonical, fmt)?;
460	    Ok(open(&decl, ctx)?)
461	}
462	
463	/// Writes `to` unless the manifest already has it, and refuses any version other than `from`:
464	/// the precondition that makes re-running an interrupted apply safe. Returns whether it wrote.
465	fn write_version_guarded(
466	    handle: &mut dyn Manifest,
467	    path: &Path,
468	    from: &Version,
469	    to: &Version,
470	    permit: &ApplyPermit,
471	) -> Result<bool, GraphError> {
472	    let current = handle.current_version()?;
473	    if current == *to {
474	        return Ok(false);
475	    }
476	    if current != *from {
477	        return Err(GraphError::UnexpectedManifestVersion {
478	            path: path.to_path_buf(),
479	            expected_from: from.clone(),
480	            expected_to: to.clone(),
481	            found: current,
482	        });
483	    }
484	    handle.write_version(to, permit)?;
485	    Ok(true)
486	}
487	
488	fn rewrite_dependency(
489	    handle: &mut dyn Manifest,
490	    rewrite: &SpecRewrite,
491	    permit: &ApplyPermit,
492	) -> Result<(), GraphError> {
493	    handle.update_dependency_spec(
494	        &rewrite.key.name,
495	        rewrite.key.kind.unwrap_or(DepKind::Runtime),
496	        &rewrite.key.locator,
497	        rewrite.to.clone(),
498	        permit,
499	    )?;
500	    Ok(())
501	}
