41	impl PackageJson {
42	    pub fn open(decl: &ManifestDecl, ctx: &OpenContext<'_>) -> Result<Self, ManifestError> {
43	        let rel_path = decl.path.clone();
44	        let abs_path = ctx.workspace_root.join(&rel_path);
45	
46	        let content = fs::read_to_string(&abs_path).map_err(|e| ManifestError::Read {
47	            path: rel_path.clone(),
48	            message: e.to_string(),
49	        })?;
50	
51	        let common_fp = crate::common::FormatFingerprint::detect(&content);
52	        let clean_content = content.strip_prefix('\u{FEFF}').unwrap_or(&content);
53	        let fingerprint = detect_fingerprint(clean_content, common_fp);
54	
55	        let doc: Map<String, Value> = serde_json::from_str(clean_content).map_err(|e| ManifestError::Parse {
56	            path: rel_path.clone(),
57	            format: ManifestFormat::PackageJson,
58	            message: e.to_string(),
59	        })?;
60	
61	        Ok(PackageJson {
62	            path: rel_path,
63	            absolute: abs_path,
64	            role: decl.role.clone(),
65	            source_doc: doc.clone(),
66	            source: clean_content.to_owned(),
67	            doc,
68	            fingerprint,
69	            npm_workspace_kind: ctx.npm_workspace_kind,
70	            workspace_root: ctx.workspace_root.to_path_buf(),
71	        })
72	    }
73	
74	    /// Writes `text` (without its byte order mark, which is put back when the file had one) and remembers it as the
75	    /// file's content, so the next change is measured against what is now on disk.
76	    fn write_text(&mut self, text: String, permit: &ApplyPermit) -> Result<(), ManifestError> {
77	        let on_disk = if self.fingerprint.common.has_bom {
78	            format!("\u{FEFF}{text}")
79	        } else {
80	            text.clone()
81	        };
82	        crate::atomic::atomic_write(&self.absolute, &on_disk, permit).map_err(|e| ManifestError::Write {
83	            path: self.path.clone(),
84	            message: e.to_string(),
85	        })?;
86	        crate::record_persist_call();
87	        self.source = text;
88	        self.source_doc = self.doc.clone();
89	        Ok(())
90	    }
91	
92	    fn dependency_target(&self, name: &str, spec: &DepSpec) -> String {
93	        let DepSpec::WorkspaceProtocol(workspace) = spec else {
94	            return name.to_string();
95	        };
96	        if let Some(alias) = workspace.alias() {
97	            return alias.to_string();
98	        }
99	        let Some(relative) = workspace.relative_path() else {
100	            return name.to_string();
101	        };
102	        let target_name = self.absolute.parent().and_then(|parent| {
103	            let target = parent.join(relative).canonicalize().ok()?;
104	            let root = self.workspace_root.canonicalize().ok()?;
105	            if !target.starts_with(root) {
106	                return None;
107	            }
108	            let manifest = target.join("package.json");
109	            let source = fs::read_to_string(&manifest).ok()?;
110	            identity_from_source(&source, &manifest).ok()?.name
111	        });
112	        target_name.unwrap_or_else(|| format!("workspace:{}", workspace.suffix))
113	    }
114	}
