116	fn detect_fingerprint(content: &str, common: crate::common::FormatFingerprint) -> FormatFingerprint {
117	    let trailing_newline = content.ends_with('\n');
118	
119	    let mut indent = Indent::DefaultTwoSpaces;
120	    for line in content.lines() {
121	        let trimmed_start = line.trim_start();
122	        if trimmed_start.starts_with('"') && line.len() > trimmed_start.len() {
123	            let leading = &line[..line.len() - trimmed_start.len()];
124	            if leading.contains('\t') {
125	                indent = Indent::Tabs;
126	            } else {
127	                indent = Indent::Spaces(leading.len() as u8);
128	            }
129	            break;
130	        }
131	    }
132	
133	    FormatFingerprint {
134	        indent,
135	        trailing_newline,
136	        common,
137	    }
138	}
