140	fn format_json_pretty(map: &IndexMap<&String, &Value>, indent_str: &str) -> Result<String, ManifestError> {
141	    use serde::Serialize;
142	    let buf = Vec::new();
143	    let formatter = serde_json::ser::PrettyFormatter::with_indent(indent_str.as_bytes());
144	    let mut serializer = serde_json::Serializer::with_formatter(buf, formatter);
145	    map.serialize(&mut serializer)
146	        .map_err(|e| ManifestError::FormattingNotPreserved {
147	            path: std::path::PathBuf::new(),
148	            message: format!("JSON serialization failed: {e}"),
149	        })?;
150	    let bytes = serializer.into_inner();
151	    let mut out = String::from_utf8(bytes).map_err(|e| ManifestError::FormattingNotPreserved {
152	        path: std::path::PathBuf::new(),
153	        message: format!("JSON serialization produced invalid UTF-8: {e}"),
154	    })?;
155	    out.push('\n');
156	    Ok(out)
157	}
