159	/// Extracts `name` from an already-parsed `package.json` document. Pure and
160	/// I/O-free -- see [`crate::cargo::cargo_package_name`]'s doc comment for
161	/// why this exists as a standalone function rather than only living inside
162	/// [`Manifest::package_name`].
163	pub fn npm_package_name(doc: &serde_json::Map<String, serde_json::Value>) -> Option<&str> {
164	    doc.get("name").and_then(|n| n.as_str())
