188	/// Reads `napi.targets` from an already-parsed `package.json` value.
189	/// `Ok(None)` when `napi` or `napi.targets` is absent -- not every napi
190	/// package.json declares platform targets. `Err` when `napi.targets` is
191	/// present but is not a JSON array of strings.
192	///
193	/// The single implementation both `NapiTargetsIndex::load` (lenient: `.ok()`
194	/// this, treating a malformed value the same as absent) and
195	/// `matrix::read_napi_targets` (strict: propagates the error) build their
196	/// differing policies on top of -- see each call site for which it chooses.
197	pub fn read_napi_targets(path: &Path, val: &Value) -> Result<Option<Vec<String>>, ManifestError> {
198	    let Some(napi) = val.get("napi") else {
199	        return Ok(None);
200	    };
201	    let Some(targets) = napi.get("targets") else {
202	        return Ok(None);
203	    };
204	
205	    let arr = targets.as_array().ok_or_else(|| ManifestError::Parse {
206	        path: path.to_path_buf(),
207	        format: ManifestFormat::PackageJson,
208	        message: "napi.targets must be a JSON array of strings".to_string(),
209	    })?;
210	
211	    let mut out = Vec::with_capacity(arr.len());
212	    for item in arr {
213	        let s = item.as_str().ok_or_else(|| ManifestError::Parse {
214	            path: path.to_path_buf(),
215	            format: ManifestFormat::PackageJson,
216	            message: "napi.targets entries must all be strings".to_string(),
217	        })?;
218	        out.push(s.to_string());
219	    }
220	    Ok(Some(out))
221	}
