223	/// The napi-rs binary name: `napi.binaryName`, else the deprecated `napi.name`, else napi-rs's `index`.
224	pub fn napi_binary_name(val: &Value) -> String {
225	    let napi = val.get("napi");
226	    ["binaryName", "name"]
227	        .iter()
228	        .find_map(|key| napi.and_then(|napi| napi.get(key)).and_then(Value::as_str))
229	        .unwrap_or("index")
230	        .to_owned()
