233	/// Detects whether `doc` (an already-parsed `package.json` document) declares
234	/// itself a napi-rs platform package -- `os`+`cpu` constraint arrays both
235	/// present and non-empty -- and if so, its platform/arch/abi. Pure and
236	/// I/O-free: the single implementation [`PackageJson::npm_role`] builds on,
237	/// so platform-role detection is available from an already-open `Manifest`
238	/// handle (e.g. one served from `callisto-graph`'s `manifest_cache`) without
239	/// a second `fs::read` of the same file.
240	/// `npm_role_from_doc` over raw `package.json` source, for callers (workspace
241	/// discovery) that have not opened a manifest handle. `None` on invalid JSON.
242	pub fn npm_role_from_source(source: &str) -> Option<NpmRole> {
243	    match serde_json::from_str::<Value>(without_bom(source)).ok()? {
244	        Value::Object(doc) => npm_role_from_doc(&doc),
245	        _ => None,
246	    }
247	}
