249	/// True when raw `package.json` `source` sets `"private": true`. `false` on
250	/// invalid JSON or an absent/non-true `private` field.
251	pub fn npm_declares_private(source: &str) -> bool {
252	    match serde_json::from_str::<Value>(without_bom(source)).ok() {
253	        Some(Value::Object(doc)) => doc.get("private").and_then(Value::as_bool).unwrap_or(false),
254	        _ => false,
255	    }
256	}
