258	/// `package.json` source without a leading byte-order mark, which every other reader of the file ignores.
259	fn without_bom(source: &str) -> &str {
260	    source.strip_prefix('\u{feff}').unwrap_or(source)
261	}
262	
263	fn npm_role_from_doc(doc: &Map<String, Value>) -> Option<NpmRole> {
264	    let has_os = doc.get("os").and_then(|v| v.as_array()).is_some_and(|a| !a.is_empty());
265	    let has_cpu = doc.get("cpu").and_then(|v| v.as_array()).is_some_and(|a| !a.is_empty());
266	
267	    if !has_os || !has_cpu {
268	        return None;
269	    }
270	
271	    let platform = doc
272	        .get("os")
273	        .and_then(|v| v.as_array())
274	        .and_then(|a| a.first())
275	        .and_then(|v| v.as_str())
276	        .map(str::to_string)?;
277	
278	    let arch = doc
279	        .get("cpu")
280	        .and_then(|v| v.as_array())
281	        .and_then(|a| a.first())
282	        .and_then(|v| v.as_str())
283	        .map(str::to_string)?;
284	
285	    // npm's standard `os`/`cpu` manifest fields have no libc/ABI concept at
286	    // all, so a real disk-discovered Linux napi platform package always
287	    // produces `abi: None` here -- but `napi.rs::role_to_triple`'s Linux
288	    // match arms all require a concrete ABI, meaning such a package could
289	    // never resolve to its triple. napi-rs's own package-generation
290	    // convention encodes the ABI in the package *name*'s suffix instead
291	    // (e.g. "@scope/pkg-linux-x64-gnu"), so infer it from there when the
292	    // platform is linux.
293	    let abi = if platform == "linux" {
294	        doc.get("name")
295	            .and_then(|v| v.as_str())
296	            .and_then(napi_linux_abi_from_package_name)
297	    } else {
298	        None
299	    };
300	
301	    Some(NpmRole::Platform { platform, arch, abi })
302	}
303	
304	/// Infers a Linux napi-rs platform package's libc ABI from its package
305	/// name's trailing suffix. Returns `None` when the name has no recognized
306	/// suffix -- this infers when the signal is present, it doesn't invent an
307	/// ABI that isn't actually there.
308	fn napi_linux_abi_from_package_name(name: &str) -> Option<String> {
309	    for abi in ["gnueabihf", "gnu", "musl"] {
310	        if name.ends_with(&format!("-{abi}")) {
311	            return Some(abi.to_string());
312	        }
313	    }
314	    None
315	}
