317	impl Manifest for PackageJson {
318	    fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError> {
319	        // A version or dependency range is a string, so the usual change is the same file with a few literals replaced.
320	        // The result must parse to exactly the document being written, or the whole file is written instead.
321	        let in_place = crate::json_text::string_edits(&self.source_doc, &self.doc)
322	            .and_then(|edits| crate::json_text::replace_strings(&self.source, &edits))
323	            .filter(|text| serde_json::from_str::<Map<String, Value>>(text).is_ok_and(|parsed| parsed == self.doc));
324	        if let Some(text) = in_place {
325	            return self.write_text(text, permit);
326	        }
327	        let indent_str = match self.fingerprint.indent {
328	            Indent::Spaces(n) => " ".repeat(n as usize),
329	            Indent::Tabs => "\t".to_string(),
330	            Indent::DefaultTwoSpaces => "  ".to_string(),
331	        };
332	
333	        let mut map = IndexMap::new();
334	        for (k, v) in &self.doc {
335	            map.insert(k, v);
336	        }
337	
338	        let mut out = format_json_pretty(&map, &indent_str)?;
339	        if self.fingerprint.common.line_ending == crate::common::LineEnding::CrLf {
340	            out = out.replace("\r\n", "\n").replace('\n', "\r\n");
341	        }
342	
343	        // Trailing-newline trimming must happen strictly between the
344	        // line-ending conversion (above, so a trimmed "\r\n" is measured
345	        // correctly) and the BOM prepend (below, so a BOM byte is never
346	        // mistaken for part of the trailing newline) -- this ordering
347	        // dependency is why npm's own trailing_newline concern can't route
348	        // through `common::FormatFingerprint::apply`'s single combined
349	        // crlf-then-bom step the way cargo/python's simpler persist paths do.
350	        if !self.fingerprint.trailing_newline && out.ends_with('\n') {
351	            if out.ends_with("\r\n") {
352	                out.truncate(out.len() - 2);
353	            } else {
354	                out.truncate(out.len() - 1);
355	            }
356	        }
357	
358	        self.write_text(out, permit)
359	    }
