369	    fn is_publishable(&self) -> bool {
370	        if self.doc.get("name").is_none() {
371	            return false;
372	        }
373	        if let Some(b) = self.doc.get("private").and_then(|p| p.as_bool())
374	            && b
375	        {
376	            return false;
377	        }
378	        true
379	    }
