381	    fn publish_targets(&self) -> Vec<callisto_model::PublishTarget> {
382	        if !self.is_publishable() {
383	            return vec![callisto_model::PublishTarget::None];
384	        }
385	        // Read `publishConfig.registry` from package.json, the standard npm
386	        // mechanism for targeting a private registry. When set, `npm publish`
387	        // must receive `--registry <url>`; when absent, the public registry is
388	        // used (npm's built-in default).
389	        let publish_config = self.doc.get("publishConfig");
390	        let registry = publish_config
391	            .and_then(|pc| pc.get("registry"))
392	            .and_then(|r| r.as_str())
393	            .map(|s| s.to_string());
394	        // Read `publishConfig.access` to propagate the operator's explicit
395	        // access intent. npm's `--access` CLI flag overrides publishConfig.access,
396	        // so callisto must read it here and honour it in release planning rather than
397	        // blindly passing `--access public` for all scoped packages. Any value
398	        // other than the two npm recognises (including absence) is `None`,
399	        // not an error -- an unrecognised value here isn't this layer's job
400	        // to validate.
401	        let access = publish_config
402	            .and_then(|pc| pc.get("access"))
403	            .and_then(|a| a.as_str())
404	            .and_then(|s| match s {
405	                "public" => Some(callisto_model::NpmAccess::Public),
406	                "restricted" => Some(callisto_model::NpmAccess::Restricted),
407	                _ => None,
408	            });
409	        vec![callisto_model::PublishTarget::Npm { registry, access }]
410	    }
