447	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = DependencyEntry> + '_> {
448	        let mut entries = Vec::new();
449	
450	        for (section_name, kind) in [
451	            ("dependencies", DepKind::Runtime),
452	            ("devDependencies", DepKind::Dev),
453	            ("peerDependencies", DepKind::Peer),
454	            ("optionalDependencies", DepKind::Optional),
455	        ] {
456	            if let Some(obj) = self.doc.get(section_name).and_then(|v| v.as_object()) {
457	                for (name, val) in obj {
458	                    if let Some(v_str) = val.as_str() {
459	                        let spec = parse_npm_spec_str(v_str, self.npm_workspace_kind);
460	                        entries.push(DependencyEntry {
461	                            name: name.clone(),
462	                            package_name: self.dependency_target(name, &spec),
463	                            kind,
464	                            spec,
465	                            inherited: false,
466	                            locator: DepLocator::default(),
467	                        });
468	                    }
469	                }
470	            }
471	        }
472	
473	        Box::new(entries.into_iter())
474	    }
