476	    fn update_dependency_spec(
477	        &mut self,
478	        name: &str,
479	        kind: DepKind,
480	        _at: &DepLocator,
481	        new: DepSpec,
482	        _permit: &ApplyPermit,
483	    ) -> Result<(), ManifestError> {
484	        if kind == DepKind::Build {
485	            return Err(ManifestError::DependencyNotFound {
486	                path: self.path.clone(),
487	                name: name.to_string(),
488	                kind,
489	            });
490	        }
491	
492	        let section_name = match kind {
493	            DepKind::Runtime => "dependencies",
494	            DepKind::Dev => "devDependencies",
495	            DepKind::Peer => "peerDependencies",
496	            DepKind::Optional => "optionalDependencies",
497	            DepKind::Build => unreachable!(),
498	        };
499	
500	        // Validate that the target dependency actually exists in the primary
501	        // section *before* mutating anything. This guarantees that a failed
502	        // update (dependency not found) leaves self.doc byte-for-byte
503	        // unchanged, including the overrides/resolutions tables below.
504	        let updated_in_section = self
505	            .doc
506	            .get(section_name)
507	            .and_then(|v| v.as_object())
508	            .is_some_and(|section| section.contains_key(name));
509	
510	        if !updated_in_section {
511	            return Err(ManifestError::DependencyNotFound {
512	                path: self.path.clone(),
513	                name: name.to_string(),
514	                kind,
515	            });
516	        }
517	
518	        if let Some(section) = self.doc.get_mut(section_name).and_then(|v| v.as_object_mut()) {
519	            section.insert(name.to_string(), Value::String(new.render()));
520	        }
521	
522	        if matches!(new, DepSpec::WorkspaceProtocol(_)) {
523	            return Ok(());
524	        }
525	
526	        for extra in ["overrides", "resolutions"] {
527	            if let Some(tbl) = self.doc.get_mut(extra).and_then(|v| v.as_object_mut())
528	                && tbl.get(name).is_some_and(|v| v.is_string())
529	            {
530	                tbl.insert(name.to_string(), Value::String(new.render()));
531	            }
532	        }
533	
534	        Ok(())
535	    }
