563	    fn bin_names(&self) -> Result<Vec<String>, ManifestError> {
564	        Ok(match self.doc.get("bin") {
565	            // npm installs a string `bin` under the unscoped package name.
566	            Some(Value::String(_)) => npm_package_name(&self.doc)
567	                .map(|name| name.rsplit('/').next().unwrap_or(name).to_string())
568	                .into_iter()
569	                .collect(),
570	            Some(Value::Object(bins)) => bins.keys().cloned().collect(),
571	            _ => Vec::new(),
