576	fn parse_npm_spec_str(s: &str, ws_kind: Option<WorkspaceKind>) -> DepSpec {
577	    if let Some(rest) = s.strip_prefix("workspace:") {
578	        if let Some(kind) = ws_kind {
579	            return DepSpec::WorkspaceProtocol(WorkspaceSpec {
580	                kind,
581	                suffix: rest.to_string(),
582	            });
583	        }
584	        return DepSpec::Opaque(format!("workspace:{rest}"));
585	    }
586	    if let Some(rest) = s.strip_prefix("catalog:") {
587	        let name = if rest.is_empty() { None } else { Some(rest.to_string()) };
588	        return DepSpec::Catalog(name);
589	    }
590	
591	    if crate::common::is_bare_semver(s)
592	        && let Ok(v) = Version::parse(s, VersionGrammar::SemVer)
593	    {
594	        return DepSpec::Exact(v);
595	    }
596	
597	    if let Ok(req) = VersionReq::parse(s, Ecosystem::Npm) {
598	        return DepSpec::Range(req, s.to_string());
599	    }
600	
601	    DepSpec::Opaque(s.to_string())
602	}
603	
604	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
605	    match spec {
606	        DepSpec::WorkspaceProtocol(workspace) => {
607	            if workspace.coverage(target).ok()? != callisto_model::Coverage::DoesNotCover {
608	                return None;
609	            }
610	            let range = workspace.range()?;
611	            let rewritten = if Version::parse(range, VersionGrammar::SemVer).is_ok() {
612	                target.render().to_string()
613	            } else {
614	                let req = VersionReq::parse(range, Ecosystem::Npm).ok()?;
615	                round_trip(&DepSpec::Range(req, range.to_string()), target)?.render()
616	            };
617	            let updated = workspace.with_range(&rewritten);
618	            if updated.coverage(target).ok()? != callisto_model::Coverage::Covers {
619	                return None;
620	            }
621	            Some(DepSpec::WorkspaceProtocol(updated))
622	        }
623	        DepSpec::Exact(_) => Some(DepSpec::Exact(target.clone())),
624	        DepSpec::Range(_, original) => {
625	            let (prefix, rest) = crate::common::split_single_operator_prefix(original)?;
626	            // A prerelease clause (`^2.0.0-next.0`) is one version; a hyphen range or a set of ranges is not.
627	            let core = rest.split(['-', '+']).next().unwrap_or(rest);
628	            if rest.contains([' ', '|']) || core.contains(['x', 'X', '*']) {
629	                return None;
630	            }
631	            if core != rest && Version::parse(rest, VersionGrammar::SemVer).is_err() {
632	                return None;
633	            }
634	            let rendered = format!("{prefix}{}", render_at_precision(target, core));
635	            let req = VersionReq::parse(&rendered, Ecosystem::Npm).ok()?;
636	            Some(DepSpec::Range(req, rendered))
637	        }
638	        _ => None,
639	    }
640	}
641	
642	fn render_at_precision(target: &Version, original_clause: &str) -> String {
643	    if target.is_prerelease() {
644	        return target.render().to_string();
645	    }
646	    let parts: Vec<&str> = original_clause.split('.').collect();
647	    let maj = target.major().unwrap_or(0);
648	    let min = target.minor().unwrap_or(0);
649	    let pat = target.patch().unwrap_or(0);
650	
651	    match parts.len() {
652	        1 => format!("{maj}"),
653	        2 => format!("{maj}.{min}"),
654	        _ => format!("{maj}.{min}.{pat}"),
655	    }
656	}
657	
658	pub fn detect_npm_workspace_kind(workspace_root: &Path) -> Result<Option<WorkspaceKind>, ManifestError> {
659	    let present = |name: &str| -> Result<bool, ManifestError> {
660	        let path = workspace_root.join(name);
661	        callisto_model::strict_fs::exists(&path).map_err(|e| ManifestError::Read {
662	            path,
663	            message: e.to_string(),
664	        })
665	    };
666	    if present("pnpm-lock.yaml")? || present("pnpm-workspace.yaml")? {
667	        return Ok(Some(WorkspaceKind::Pnpm));
668	    }
669	    if present("yarn.lock")? {
670	        return Ok(Some(WorkspaceKind::Yarn));
671	    }
672	    if present("package-lock.json")? {
673	        return Ok(Some(WorkspaceKind::Npm));
674	    }
675	
676	    let root_pkg_json = workspace_root.join("package.json");
677	    let content = callisto_model::strict_fs::read_optional(&root_pkg_json).map_err(|e| ManifestError::Read {
678	        path: root_pkg_json.clone(),
679	        message: e.to_string(),
680	    })?;
681	    if let Some(content) = content {
682	        let val = serde_json::from_str::<Value>(content.strip_prefix('\u{FEFF}').unwrap_or(&content)).map_err(|e| {
683	            ManifestError::Parse {
684	                path: root_pkg_json.clone(),
685	                format: ManifestFormat::PackageJson,
686	                message: e.to_string(),
687	            }
688	        })?;
689	        if val.get("workspaces").is_some() {
690	            return Ok(Some(WorkspaceKind::Npm));
691	        }
692	    }
693	
694	    Ok(None)
695	}
696	
