1	use std::fs;
2	use std::path::{Path, PathBuf};
3	
4	use callisto_model::{
5	    ApplyPermit, DepKind, DepLocator, DepSpec, DependencyEntry, Ecosystem, ManifestDecl, ManifestError, ManifestFormat,
6	    ManifestRole, Version, VersionGrammar, VersionReq, WorkspaceKind, WorkspaceSpec,
7	};
8	use indexmap::IndexMap;
9	use serde_json::{Map, Value};
10	
11	use crate::{Manifest, NpmRole, OpenContext};
12	
13	pub struct PackageJson {
14	    path: PathBuf,
15	    absolute: PathBuf,
16	    role: ManifestRole,
17	    doc: Map<String, Value>,
18	    /// The file as last read or written (byte order mark removed) and its parse, so a change that only replaces string
19	    /// values can be written into that text instead of reflowing the whole file.
20	    source: String,
21	    source_doc: Map<String, Value>,
22	    fingerprint: FormatFingerprint,
23	    npm_workspace_kind: Option<WorkspaceKind>,
24	    workspace_root: PathBuf,
25	}
26	
27	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
28	struct FormatFingerprint {
29	    indent: Indent,
30	    trailing_newline: bool,
31	    common: crate::common::FormatFingerprint,
32	}
33	
34	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
35	enum Indent {
36	    Spaces(u8),
37	    Tabs,
38	    DefaultTwoSpaces,
39	}
40	
41	impl PackageJson {
42	    pub fn open(decl: &ManifestDecl, ctx: &OpenContext<'_>) -> Result<Self, ManifestError> {
43	        let rel_path = decl.path.clone();
44	        let abs_path = ctx.workspace_root.join(&rel_path);
45	
46	        let content = fs::read_to_string(&abs_path).map_err(|e| ManifestError::Read {
47	            path: rel_path.clone(),
48	            message: e.to_string(),
49	        })?;
50	
51	        let common_fp = crate::common::FormatFingerprint::detect(&content);
52	        let clean_content = content.strip_prefix('\u{FEFF}').unwrap_or(&content);
53	        let fingerprint = detect_fingerprint(clean_content, common_fp);
54	
55	        let doc: Map<String, Value> = serde_json::from_str(clean_content).map_err(|e| ManifestError::Parse {
56	            path: rel_path.clone(),
57	            format: ManifestFormat::PackageJson,
58	            message: e.to_string(),
59	        })?;
60	
61	        Ok(PackageJson {
62	            path: rel_path,
63	            absolute: abs_path,
64	            role: decl.role.clone(),
65	            source_doc: doc.clone(),
66	            source: clean_content.to_owned(),
67	            doc,
68	            fingerprint,
69	            npm_workspace_kind: ctx.npm_workspace_kind,
70	            workspace_root: ctx.workspace_root.to_path_buf(),
71	        })
72	    }
73	
74	    /// Writes `text` (without its byte order mark, which is put back when the file had one) and remembers it as the
75	    /// file's content, so the next change is measured against what is now on disk.
76	    fn write_text(&mut self, text: String, permit: &ApplyPermit) -> Result<(), ManifestError> {
77	        let on_disk = if self.fingerprint.common.has_bom {
78	            format!("\u{FEFF}{text}")
79	        } else {
80	            text.clone()
81	        };
82	        crate::atomic::atomic_write(&self.absolute, &on_disk, permit).map_err(|e| ManifestError::Write {
83	            path: self.path.clone(),
84	            message: e.to_string(),
85	        })?;
86	        crate::record_persist_call();
87	        self.source = text;
88	        self.source_doc = self.doc.clone();
89	        Ok(())
90	    }
91	
92	    fn dependency_target(&self, name: &str, spec: &DepSpec) -> String {
93	        let DepSpec::WorkspaceProtocol(workspace) = spec else {
94	            return name.to_string();
95	        };
96	        if let Some(alias) = workspace.alias() {
97	            return alias.to_string();
98	        }
99	        let Some(relative) = workspace.relative_path() else {
100	            return name.to_string();
101	        };
102	        let target_name = self.absolute.parent().and_then(|parent| {
103	            let target = parent.join(relative).canonicalize().ok()?;
104	            let root = self.workspace_root.canonicalize().ok()?;
105	            if !target.starts_with(root) {
106	                return None;
107	            }
108	            let manifest = target.join("package.json");
109	            let source = fs::read_to_string(&manifest).ok()?;
110	            identity_from_source(&source, &manifest).ok()?.name
111	        });
112	        target_name.unwrap_or_else(|| format!("workspace:{}", workspace.suffix))
113	    }
114	}
115	
116	fn detect_fingerprint(content: &str, common: crate::common::FormatFingerprint) -> FormatFingerprint {
117	    let trailing_newline = content.ends_with('\n');
118	
119	    let mut indent = Indent::DefaultTwoSpaces;
120	    for line in content.lines() {
121	        let trimmed_start = line.trim_start();
122	        if trimmed_start.starts_with('"') && line.len() > trimmed_start.len() {
123	            let leading = &line[..line.len() - trimmed_start.len()];
124	            if leading.contains('\t') {
125	                indent = Indent::Tabs;
126	            } else {
127	                indent = Indent::Spaces(leading.len() as u8);
128	            }
129	            break;
130	        }
131	    }
132	
133	    FormatFingerprint {
134	        indent,
135	        trailing_newline,
136	        common,
137	    }
138	}
139	
140	fn format_json_pretty(map: &IndexMap<&String, &Value>, indent_str: &str) -> Result<String, ManifestError> {
141	    use serde::Serialize;
142	    let buf = Vec::new();
143	    let formatter = serde_json::ser::PrettyFormatter::with_indent(indent_str.as_bytes());
144	    let mut serializer = serde_json::Serializer::with_formatter(buf, formatter);
145	    map.serialize(&mut serializer)
146	        .map_err(|e| ManifestError::FormattingNotPreserved {
147	            path: std::path::PathBuf::new(),
148	            message: format!("JSON serialization failed: {e}"),
149	        })?;
150	    let bytes = serializer.into_inner();
151	    let mut out = String::from_utf8(bytes).map_err(|e| ManifestError::FormattingNotPreserved {
152	        path: std::path::PathBuf::new(),
153	        message: format!("JSON serialization produced invalid UTF-8: {e}"),
154	    })?;
155	    out.push('\n');
156	    Ok(out)
157	}
158	
159	/// Extracts `name` from an already-parsed `package.json` document. Pure and
160	/// I/O-free -- see [`crate::cargo::cargo_package_name`]'s doc comment for
161	/// why this exists as a standalone function rather than only living inside
162	/// [`Manifest::package_name`].
163	pub fn npm_package_name(doc: &serde_json::Map<String, serde_json::Value>) -> Option<&str> {
164	    doc.get("name").and_then(|n| n.as_str())
165	}
