168	/// `source` and extracts `name` plus a [`crate::VersionSource::Literal`]
169	/// for `version` (npm has no workspace-inherited-version concept, unlike
170	/// Cargo).
171	pub(crate) fn identity_from_source(source: &str, path: &Path) -> Result<crate::ManifestIdentity, ManifestError> {
172	    let clean = source.strip_prefix('\u{FEFF}').unwrap_or(source);
173	    let doc: Map<String, Value> = serde_json::from_str(clean).map_err(|e| ManifestError::Parse {
174	        path: path.to_path_buf(),
175	        format: ManifestFormat::PackageJson,
176	        message: e.to_string(),
177	    })?;
178	
179	    let name = npm_package_name(&doc).map(str::to_string);
180	    let version = doc
181	        .get("version")
182	        .and_then(|v| v.as_str())
183	        .map(|s| crate::VersionSource::Literal(s.to_string()));
184	
185	    Ok(crate::ManifestIdentity { name, version })
186	}
