537	    fn update_optional_dependencies(
538	        &mut self,
539	        updates: &[(String, Version)],
540	        _permit: &ApplyPermit,
541	    ) -> Result<(), ManifestError> {
542	        let section = self
543	            .doc
544	            .entry("optionalDependencies".to_string())
545	            .or_insert_with(|| Value::Object(Map::new()))
546	            .as_object_mut()
547	            .ok_or_else(|| ManifestError::FormattingNotPreserved {
548	                path: self.path.clone(),
549	                message: "optionalDependencies is not an object".to_string(),
550	            })?;
551	
552	        for (name, ver) in updates {
553	            section.insert(name.clone(), Value::String(ver.render().to_string()));
554	        }
555	
556	        Ok(())
557	    }
