1	//! Replacing string values inside JSON text without touching anything else.
2	//!
3	//! Re-serializing a whole `package.json` to change one version rewrites every inline array and object in it, so a
4	//! version bump becomes a noisy diff. A change that only replaces string values is made on the original text instead.
5	
6	use jsonc_parser::cst::{CstInputValue, CstRootNode};
7	use jsonc_parser::ParseOptions;
8	use serde_json::{Map, Value};
9	
10	/// Every string value that differs between `before` and `after`, as `(key path, new value)`; `None` when they differ
11	/// in anything else (a key added or removed, a changed array, a changed type), which needs the whole document written.
12	pub(crate) fn string_edits(
13	    before: &Map<String, Value>,
14	    after: &Map<String, Value>,
15	) -> Option<Vec<(Vec<String>, String)>> {
16	    let mut edits = Vec::new();
17	    objects_differ_only_in_strings(before, after, &mut Vec::new(), &mut edits).then_some(edits)
18	}
19	
20	fn objects_differ_only_in_strings(
21	    before: &Map<String, Value>,
22	    after: &Map<String, Value>,
23	    path: &mut Vec<String>,
24	    edits: &mut Vec<(Vec<String>, String)>,
25	) -> bool {
26	    if before.len() != after.len() {
27	        return false;
28	    }
29	    for (key, old) in before {
30	        let Some(new) = after.get(key) else {
31	            return false;
32	        };
33	        path.push(key.clone());
34	        let same_shape = match (old, new) {
35	            (Value::String(old), Value::String(new)) => {
36	                if old != new {
37	                    edits.push((path.clone(), new.clone()));
38	                }
39	                true
40	            }
41	            (Value::Object(old), Value::Object(new)) => objects_differ_only_in_strings(old, new, path, edits),
42	            (old, new) => old == new,
43	        };
44	        path.pop();
45	        if !same_shape {
46	            return false;
47	        }
48	    }
49	    true
50	}
