52	/// `source` with each edit's string value replaced; `None` when a path does not lead to an existing string.
53	pub(crate) fn replace_strings(source: &str, edits: &[(Vec<String>, String)]) -> Option<String> {
54	    let root = CstRootNode::parse(source, &ParseOptions::default()).ok()?;
55	    for (path, value) in edits {
56	        let (last, parents) = path.split_last()?;
57	        let mut object = root.object_value()?;
58	        for key in parents {
59	            object = object.object_value(key)?;
60	        }
61	        let property = object.get(last)?;
62	        property.value()?.as_string_lit()?;
63	        property.set_value(CstInputValue::String(value.clone()));
64	    }
65	    Some(root.to_string())
66	}
