219	/// Splits a bare `major[.minor[.patch]]` version core (no pre-release/local
220	/// suffix, at most three dotted integer components) into its components.
221	/// Returns `None` for anything else -- a caret/tilde/wildcard clause whose
222	/// core doesn't fit this shape (e.g. `^1.2.3-beta`) is not normalized here;
223	/// the caller falls through to a raw PEP 440 parse attempt (which will fail)
224	/// and ultimately an opaque fallback, rather than mis-normalizing it.
225	fn parse_version_core(s: &str) -> Option<(u64, Option<u64>, Option<u64>)> {
226	    let mut parts = s.split('.');
227	    let major: u64 = parts.next()?.parse().ok()?;
228	    let minor = parts.next().map(str::parse).transpose().ok()?;
229	    let patch = parts.next().map(str::parse).transpose().ok()?;
230	    if parts.next().is_some() {
231	        return None;
232	    }
233	    Some((major, minor, patch))
234	}
235	
236	/// Expands a Poetry caret clause's version core (the part after `^`) into an
237	/// equivalent PEP 440 range. Caret allows changes that do not modify the
238	/// leftmost non-zero component of `major.minor.patch` -- see
239	/// <https://python-poetry.org/docs/dependency-specification/#caret-requirements>.
240	fn normalize_caret(rest: &str) -> Option<String> {
241	    let (major, minor, patch) = parse_version_core(rest)?;
242	    let lower = format!("{major}.{}.{}", minor.unwrap_or(0), patch.unwrap_or(0));
243	
244	    let upper = if major > 0 {
245	        format!("{}.0.0", major + 1)
246	    } else if let Some(min) = minor {
247	        if min > 0 {
248	            format!("0.{}.0", min + 1)
249	        } else if let Some(pat) = patch {
250	            format!("0.0.{}", pat + 1)
251	        } else {
252	            "0.1.0".to_string()
253	        }
254	    } else {
255	        "1.0.0".to_string()
256	    };
257	
258	    Some(format!(">={lower},<{upper}"))
259	}
260	
261	/// Expands a Poetry tilde clause's version core (the part after `~`) into an
262	/// equivalent PEP 440 range. Tilde allows patch-level changes when a minor
263	/// version is given, otherwise major-level changes -- see
264	/// <https://python-poetry.org/docs/dependency-specification/#tilde-requirements>.
265	fn normalize_tilde(rest: &str) -> Option<String> {
266	    let (major, minor, patch) = parse_version_core(rest)?;
267	    let lower = format!("{major}.{}.{}", minor.unwrap_or(0), patch.unwrap_or(0));
268	    let upper = match minor {
269	        Some(min) => format!("{major}.{}.0", min + 1),
270	        None => format!("{}.0.0", major + 1),
271	    };
272	    Some(format!(">={lower},<{upper}"))
273	}
274	
275	/// Expands a bare Poetry wildcard clause (`1.*`, `1.2.*`) into an equivalent
276	/// PEP 440 range. Does not handle wildcards already attached to an explicit
277	/// operator (`==1.2.*`, `!=1.2.*`) -- those are valid PEP 440 as-is and must
278	/// not reach this function (see `normalize_poetry_clause`).
279	fn normalize_wildcard(clause: &str) -> Option<String> {
280	    let core = clause.strip_suffix(".*")?;
281	    if core.is_empty() {
282	        return None;
283	    }
284	    let mut parts = core.split('.');
285	    let major: u64 = parts.next()?.parse().ok()?;
286	    match parts.next() {
287	        None => Some(format!(">={major}.0.0,<{}.0.0", major + 1)),
288	        Some(minor_str) => {
289	            if parts.next().is_some() {
290	                return None;
291	            }
292	            let minor: u64 = minor_str.parse().ok()?;
293	            Some(format!(">={major}.{minor}.0,<{major}.{}.0", minor + 1))
294	        }
295	    }
296	}
297	
298	/// Normalizes a single comma-separated clause of a Poetry version
299	/// constraint. Only bare caret/tilde/wildcard clauses are rewritten; a
300	/// clause that's already PEP 440-compatible (`>=1.2`, `~=1.2.3`, `==1.2.*`)
301	/// passes through unchanged, since Poetry accepts standard PEP 440 syntax
302	/// verbatim alongside its own caret/tilde/wildcard extensions.
303	fn normalize_poetry_clause(clause: &str) -> String {
304	    if clause == "*" {
305	        return String::new();
306	    }
307	    if let Some(rest) = clause.strip_prefix('^') {
308	        if let Some(normalized) = normalize_caret(rest) {
309	            return normalized;
310	        }
311	    } else if let Some(rest) = clause.strip_prefix('~') {
312	        // Distinguish Poetry's bare tilde ("~1.2.3") from PEP 440's
313	        // compatible-release operator ("~=1.2.3"), which is already valid.
314	        if !rest.starts_with('=')
315	            && let Some(normalized) = normalize_tilde(rest)
316	        {
317	            return normalized;
318	        }
319	    } else if clause.starts_with(|c: char| c.is_ascii_digit())
320	        && clause.contains('*')
321	        && let Some(normalized) = normalize_wildcard(clause)
322	    {
323	        return normalized;
324	    }
325	    clause.to_string()
326	}
327	
328	/// Normalizes a Poetry-style version constraint -- which allows caret (`^`),
329	/// tilde (`~`), and wildcard (`*`) syntax on top of PEP 440, see
330	/// <https://python-poetry.org/docs/dependency-specification/#version-constraints>
331	/// -- into a comma-joined PEP 440 range string that `pep440_rs` can parse
332	/// directly.
333	///
334	/// Each comma-separated clause is normalized independently, so compound
335	/// constraints like `^1.2,!=1.2.5` are handled correctly. A clause this
336	/// normalizer doesn't recognize (or can't decompose, e.g. a caret applied to
337	/// a pre-release version) passes through unchanged; the subsequent
338	/// `VersionReq::parse` attempt then fails on it, and the caller falls back
339	/// to an opaque dependency entry rather than silently dropping the
340	/// dependency.
341	fn normalize_poetry_version_spec(raw: &str) -> String {
342	    raw.split(',')
343	        .map(str::trim)
344	        .filter(|clause| !clause.is_empty())
345	        .map(normalize_poetry_clause)
346	        .filter(|clause| !clause.is_empty())
347	        .collect::<Vec<_>>()
348	        .join(",")
349	}
