401	            .or_else(|| {
402	                self.document
403	                    .get("tool")
404	                    .and_then(|t| t.get("poetry"))
405	                    .and_then(|p| p.get("version"))
406	                    .and_then(|v| v.as_str())
407	            })
408	            // 3. Flit [tool.flit.metadata].version
409	            .or_else(|| {
410	                self.document
411	                    .get("tool")
412	                    .and_then(|t| t.get("flit"))
413	                    .and_then(|f| f.get("metadata"))
414	                    .and_then(|m| m.get("version"))
415	                    .and_then(|v| v.as_str())
416	            });
417	
418	        let raw = raw_ver.ok_or_else(|| ManifestError::MissingField {
419	            path: self.path.clone(),
420	            field: "project.version / tool.poetry.version",
421	        })?;
422	
423	        Version::parse(raw, VersionGrammar::Pep440).map_err(|e| ManifestError::InvalidVersion {
424	            path: self.path.clone(),
425	            raw: raw.to_string(),
426	            source: e,
427	        })
428	    }
429	
430	    fn write_version(&mut self, v: &Version, _permit: &ApplyPermit) -> Result<(), ManifestError> {
431	        let new_ver = v.render();
432	
433	        let has_project_version = self.document.get("project").and_then(|p| p.get("version")).is_some();
434	
435	        if has_project_version {
436	            if let Some(proj) = self.document.get_mut("project").and_then(|p| p.as_table_like_mut()) {
437	                crate::common::set_scalar_preserving_decor(proj, "version", new_ver);
438	            }
439	        } else if let Some(poetry) = self
440	            .document
441	            .get_mut("tool")
442	            .and_then(|t| t.get_mut("poetry"))
443	            .and_then(|p| p.as_table_like_mut())
444	        {
445	            crate::common::set_scalar_preserving_decor(poetry, "version", new_ver);
446	        } else if let Some(flit) = self
447	            .document
448	            .get_mut("tool")
449	            .and_then(|t| t.get_mut("flit"))
450	            .and_then(|f| f.get_mut("metadata"))
451	            .and_then(|m| m.as_table_like_mut())
452	        {
453	            crate::common::set_scalar_preserving_decor(flit, "version", new_ver);
454	        } else {
455	            self.document["project"]["version"] = value(new_ver);
456	        }
457	
458	        Ok(())
459	    }
460	
461	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = DependencyEntry> + '_> {
462	        let mut entries = Vec::new();
463	
464	        // 1. PEP 621 [project].dependencies (array of requirement strings)
465	        if let Some(deps) = self
466	            .document
467	            .get("project")
468	            .and_then(|p| p.get("dependencies"))
469	            .and_then(|d| d.as_array())
470	        {
471	            entries.extend(requirement_entries(
472	                deps,
473	                DepKind::Runtime,
474	                &DepContainer::ProjectDependencies,
475	            ));
476	        }
477	
478	        // 1b. PEP 621 [project.optional-dependencies]: extras ship in the published metadata, so a
479	        // pin there goes stale exactly like a runtime one.
480	        if let Some(extras) = self
481	            .document
482	            .get("project")
483	            .and_then(|p| p.get("optional-dependencies"))
484	            .and_then(|d| d.as_table_like())
485	        {
486	            for (extra, group) in extras.iter() {
487	                if let Some(requirements) = group.as_array() {
488	                    entries.extend(requirement_entries(
489	                        requirements,
490	                        DepKind::Optional,
491	                        &DepContainer::Extra(extra.to_string()),
492	                    ));
493	                }
494	            }
495	        }
496	
497	        // 2. Poetry [tool.poetry.dependencies]
498	        if let Some(table) = self
499	            .document
500	            .get("tool")
501	            .and_then(|t| t.get("poetry"))
502	            .and_then(|p| p.get("dependencies"))
503	            .and_then(|d| d.as_table_like())
504	        {
505	            for (name, item) in table.iter() {
506	                if name == "python" {
507	                    continue;
508	                }
509	                // `as_table_like()` covers both inline tables
510	                // (`foo = { version = "^1.2" }`) and dotted-table syntax
511	                // (`[tool.poetry.dependencies.foo]` / `version = "^1.2"`),
512	                // which parse to different `toml_edit::Item` variants but
513	                // must both be recognized -- previously only the inline-table
514	                // variant was handled, so a dotted-table Poetry dependency
515	                // silently vanished from the graph entirely.
516	                let raw_req = match item {
517	                    toml_edit::Item::Value(toml_edit::Value::String(s)) => Some(s.value().as_str()),
518	                    _ => item
519	                        .as_table_like()
520	                        .and_then(|t| t.get("version"))
521	                        .and_then(|v| v.as_str()),
522	                };
523	
524	                let spec = match raw_req {
525	                    Some(req_str) => {
526	                        // Poetry allows caret/tilde/wildcard syntax on top of
527	                        // PEP 440 (e.g. `^1.2`, `~1.2.3`, `1.*`), which
528	                        // `pep440_rs` cannot parse directly -- normalize it
529	                        // to an equivalent PEP 440 range first.
530	                        let normalized = normalize_poetry_version_spec(req_str);
531	                        match VersionReq::parse(&normalized, Ecosystem::Pypi) {
532	                            Ok(spec) => DepSpec::Range(spec, req_str.to_string()),
533	                            // Genuinely unrepresentable (syntax this
534	                            // normalizer doesn't cover) -- never silently
535	                            // drop the dependency; keep it visible in the
536	                            // graph as an opaque spec instead.
537	                            Err(_) => DepSpec::Opaque(req_str.to_string()),
538	                        }
539	                    }
540	                    // No `version` key at all -- a path/git/url dependency
541	                    // (e.g. `foo = { git = "...", tag = "v1.0" }`) or an
542	                    // unrecognized value shape. Still must not silently
543	                    // vanish from the graph.
544	                    None => {
545	                        DepSpec::Opaque("non-versioned dependency (path/git/url or unrecognized shape)".to_string())
546	                    }
547	                };
548	
549	                entries.push(DependencyEntry {
550	                    name: name.to_string(),
551	                    package_name: name.to_string(),
552	                    inherited: false,
553	                    kind: DepKind::Runtime,
554	                    spec,
555	                    locator: DepLocator::python(DepContainer::PoetryDependencies, None),
556	                });
557	            }
558	        }
559	
560	        Box::new(entries.into_iter())
561	    }
562	
563	    fn update_dependency_spec(
564	        &mut self,
565	        name: &str,
566	        kind: DepKind,
567	        at: &DepLocator,
568	        new: DepSpec,
569	        _permit: &ApplyPermit,
570	    ) -> Result<(), ManifestError> {
571	        let new_spec_str = match new {
572	            DepSpec::Range(req, _) => req.render().to_string(),
573	            DepSpec::Exact(v) => format!("=={}", v.render()),
574	            _ => return Ok(()),
575	        };
576	        let not_found = || ManifestError::DependencyNotFound {
577	            path: self.path.clone(),
578	            name: name.to_string(),
579	            kind,
580	        };
581	
582	        let DepLocator::Python {
583	            container, position, ..
584	        } = at
585	        else {
586	            return Err(not_found());
587	        };
588	        match container {
589	            DepContainer::PoetryDependencies => {
590	                let table = self
591	                    .document
592	                    .get_mut("tool")
593	                    .and_then(|t| t.get_mut("poetry"))
594	                    .and_then(|p| p.get_mut("dependencies"))
595	                    .and_then(|d| d.as_table_like_mut())
596	                    .ok_or_else(not_found)?;
597	                // Edited in place, so the comment above the dependency and the one after it stay.
598	                if table.get(name).ok_or_else(not_found)?.is_table_like() {
599	                    let fields = table
600	                        .get_mut(name)
601	                        .and_then(|existing| existing.as_table_like_mut())
602	                        .ok_or_else(not_found)?;
603	                    crate::common::set_scalar_preserving_decor(fields, "version", &new_spec_str);
604	                } else {
605	                    crate::common::set_scalar_preserving_decor(table, name, &new_spec_str);
606	                }
607	            }
608	            container => {
609	                let position = position.ok_or_else(not_found)?;
610	                let requirements = match container {
611	                    DepContainer::ProjectDependencies => {
612	                        self.document.get_mut("project").and_then(|p| p.get_mut("dependencies"))
613	                    }
614	                    DepContainer::Extra(extra) => self
615	                        .document
616	                        .get_mut("project")
617	                        .and_then(|p| p.get_mut("optional-dependencies"))
618	                        .and_then(|d| d.get_mut(extra.as_str())),
619	                    _ => None,
620	                }
621	                .and_then(|item| item.as_array_mut())
622	                .ok_or_else(not_found)?;
623	                // The array may differ from the one the locator was read from: refuse to rewrite another dependency.
624	                let rewritten = requirements
625	                    .get(position)
626	                    .and_then(|item| item.as_str())
627	                    .and_then(|full_req| rewrite_requirement(full_req, name, &new_spec_str))
628	                    .ok_or_else(not_found)?;
629	                requirements.replace(position, rewritten);
630	            }
631	        }
632	
633	        Ok(())
634	    }
635	
636	    fn is_publishable(&self) -> bool {
637	        // A pyproject.toml without [project].name or [tool.poetry].name is a
638	        // workspace root or build-system-only file — not a publishable package.
639	        let has_pep621_name = self
640	            .document
641	            .get("project")
642	            .and_then(|p| p.get("name"))
643	            .and_then(|n| n.as_str())
644	            .is_some();
645	        let has_poetry_name = self
646	            .document
647	            .get("tool")
648	            .and_then(|t| t.get("poetry"))
649	            .and_then(|p| p.get("name"))
650	            .and_then(|n| n.as_str())
651	            .is_some();
652	        has_pep621_name || has_poetry_name
653	    }
654	
655	    fn publish_targets(&self) -> Vec<PublishTarget> {
656	        if !self.is_publishable() {
657	            return vec![PublishTarget::None];
658	        }
659	        vec![PublishTarget::Pypi { index: None }]
660	    }
661	
662	    fn update_optional_dependencies(
663	        &mut self,
664	        updates: &[(String, Version)],
665	        _permit: &ApplyPermit,
666	    ) -> Result<(), ManifestError> {
667	        if updates.is_empty() {
668	            return Ok(());
669	        }
670	
671	        // [project.optional-dependencies] is a table of group_name → [PEP 508 strings].
672	        // Collect the table keys first to avoid borrow conflicts.
673	        let group_keys: Vec<String> = self
674	            .document
675	            .get("project")
676	            .and_then(|p| p.get("optional-dependencies"))
677	            .and_then(|od| od.as_table_like())
678	            .map(|t| t.iter().map(|(k, _)| k.to_string()).collect())
679	            .unwrap_or_default();
680	
681	        for group_key in &group_keys {
682	            let Some(arr) = self
683	                .document
684	                .get_mut("project")
685	                .and_then(|p| p.get_mut("optional-dependencies"))
686	                .and_then(|od| od.get_mut(group_key.as_str()))
687	                .and_then(|g| g.as_array_mut())
688	            else {
689	                continue;
690	            };
691	
692	            for idx in 0..arr.len() {
693	                let Some(full_req) = arr.get(idx).and_then(|item| item.as_str()) else {
694	                    continue;
695	                };
696	                let Some(req) = Requirement::parse(full_req) else {
697	                    continue;
698	                };
699	
700	                if let Some((_dep_name, new_ver)) = updates.iter().find(|(dep_name, _)| {
701	                    normalize_pypi_package_name(dep_name) == normalize_pypi_package_name(&req.name)
702	                }) {
703	                    let new_req = Requirement {
704	                        name: req.name.clone(),
705	                        extras: req.extras.clone(),
706	                        spec: Some(format!(">={}", new_ver.render())),
707	                        marker: req.marker.clone(),
708	                    };
709	                    arr.replace(idx, new_req.render());
710	                }
711	            }
712	        }
713	
714	        Ok(())
715	    }
716	}
