718	/// Rewrites a PEP 508 dependency constraint to pin it to `target`.
719	///
720	/// The following single-clause and two-clause forms are recognized and rewritten:
721	///
722	/// - `==X.Y.Z` — exact pin — is rewritten to `==NEW`.
723	/// - `~=X.Y.Z` — compatible release — is rewritten to `~=NEW`.
724	/// - `>=X.Y.Z` — lower bound only — is rewritten to `>=NEW`.
725	/// - `>=X.Y.Z,<A.B` — two-clause range — is rewritten to `>=NEW,<NEXT_MAJOR`
726	///   where `NEXT_MAJOR` equals `target.major() + 1`.
727	///
728	/// A pre-release or dev/local target (e.g. a `snapshot` version) is rendered
729	/// in full rather than truncated to `major.minor.patch`, the same precision
730	/// rule `cargo::round_trip` applies for SemVer.
731	///
732	/// All other forms return `None` — including upper-bound-only (`<`, `<=`),
733	/// exclusion (`!=`), compound expressions beyond the two-clause range above,
734	/// and wildcard `*`. Callers must leave the original constraint unchanged
735	/// when `None` is returned.
736	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
737	    // Only Range specs are produced by iter_dependencies for Python.
738	    let original = match spec {
739	        DepSpec::Range(_, raw) => raw.as_str(),
740	        _ => return None,
741	    };
742	
743	    let trimmed = original.trim();
744	
745	    // Compound range: ">=X.Y.Z,<A.B" → ">=NEW,<NEXT_MAJOR"
746	    if trimmed.contains(',') {
747	        return rewrite_range(trimmed, target);
748	    }
749	
750	    // Single-clause forms matched by their PEP 508 operator prefix.
751	    if trimmed.starts_with("==") {
752	        return rewrite_single(trimmed, "==", target);
753	    }
754	    if trimmed.starts_with("~=") {
755	        return rewrite_single(trimmed, "~=", target);
756	    }
757	    if trimmed.starts_with(">=") {
758	        return rewrite_single(trimmed, ">=", target);
759	    }
760	    // Poetry's own operators: bare caret and tilde (PEP 440's `~=` was handled above).
761	    if let Some(core) = trimmed.strip_prefix('^') {
762	        return rewrite_poetry_operator("^", core, target);
763	    }
764	    if let Some(core) = trimmed.strip_prefix('~').filter(|rest| !rest.starts_with('=')) {
765	        return rewrite_poetry_operator("~", core, target);
766	    }
767	
768	    // Unknown or unsupported form (e.g. "<", "<=", "!=", bare "*").
769	    None
770	}
771	
772	/// Rewrites a single-clause PEP 508 specifier, preserving the operator.
773	fn rewrite_single(original: &str, op: &str, target: &Version) -> Option<DepSpec> {
774	    // Validate that the original clause parses correctly (guards against
775	    // unknown version syntax that happens to start with a known prefix).
776	    let rest = original.strip_prefix(op)?;
777	    let mut rendered_target = render_target(op, target)?;
778	    // `~=1.2` allows any 1.x from 1.2, and `~=1.2.0` only 1.2.x, so a compatible-release clause keeps the number of
779	    // components it was written with.
780	    if op == "~="
781	        && !target.is_prerelease()
782	        && parse_version_core(rest.trim()).is_some_and(|(_, minor, patch)| minor.is_some() && patch.is_none())
783	    {
784	        rendered_target = format!("{}.{}", target.major()?, target.minor()?);
785	    }
786	    let rendered = format!("{op}{rendered_target}");
787	    let req = VersionReq::parse(&rendered, Ecosystem::Pypi).ok()?;
788	    Some(DepSpec::Range(req, rendered))
789	}
790	
791	/// Rewrites a Poetry caret or tilde clause to the same window around the stable `target`; the caller writes it as the
792	/// equivalent PEP 440 range, which Poetry reads too. A pre-release target has no caret or tilde form, so it is left alone.
793	fn rewrite_poetry_operator(op: &str, core: &str, target: &Version) -> Option<DepSpec> {
794	    parse_version_core(core)?;
795	    if target.is_prerelease() {
796	        return None;
797	    }
798	    let rendered = format!("{op}{}", render_target(op, target)?);
799	    let req = VersionReq::parse(&normalize_poetry_version_spec(&rendered), Ecosystem::Pypi).ok()?;
800	    Some(DepSpec::Range(req, rendered))
801	}
802	
803	/// Renders `target` at the precision a rewritten spec should carry, for use after `op`:
804	/// `major.minor.patch` for a stable release; the version in full for a pre-release or
805	/// dev target paired with `==`/`!=` (the only operators PEP 440 allows on a local version);
806	/// the version with its local segment stripped for every other operator, since PEP 440
807	/// forbids `>=`, `<=`, `>`, `<` and `~=` from carrying one.
808	fn render_target(op: &str, target: &Version) -> Option<String> {
809	    if target.is_prerelease() {
810	        let full = target.render();
811	        if op == "==" || op == "!=" {
812	            return Some(full.to_string());
813	        }
814	        return Some(full.split('+').next().unwrap_or(full).to_string());
815	    }
816	    Some(format!("{}.{}.{}", target.major()?, target.minor()?, target.patch()?))
817	}
818	
819	/// Rewrites a two-clause `>=X.Y.Z,<A.B` range to `>=NEW,<NEXT_MAJOR`.
820	///
821	/// Returns `None` for anything that does not match exactly this two-clause
822	/// lower/upper pattern, including specs with three or more clauses (e.g.
823	/// `>=1.0,<2.0,!=1.5.0`) where silently dropping extra clauses would produce
824	/// a semantically incorrect constraint.
825	fn rewrite_range(original: &str, target: &Version) -> Option<DepSpec> {
826	    // Reject any spec with more than two comma-separated clauses: rewriting
827	    // would silently discard the extra clauses, changing the semantics.
828	    if original.split(',').count() != 2 {
829	        return None;
830	    }
831	
832	    let mut parts = original.splitn(2, ',');
833	    let lower = parts.next()?.trim();
834	    let upper = parts.next()?.trim();
835	
836	    // Lower clause must be `>=…`.
837	    if !lower.starts_with(">=") {
838	        return None;
839	    }
840	    // Upper clause must be strictly `<…` (not `<=`).
841	    if !upper.starts_with('<') || upper.starts_with("<=") {
842	        return None;
843	    }
844	
845	    // A window of one minor (`>=0.1.0,<0.2`) stays one minor wide; any other upper bound becomes the next major.
846	    let lower_core = lower
847	        .strip_prefix(">=")
848	        .and_then(|version| parse_version_core(version.trim()));
849	    let upper_core = upper
850	        .strip_prefix('<')
851	        .and_then(|version| parse_version_core(version.trim()));
852	    let one_minor_window = matches!(
853	        (lower_core, upper_core),
854	        (Some((lower_major, Some(lower_minor), _)), Some((upper_major, Some(upper_minor), upper_patch)))
855	            if upper_major == lower_major && upper_minor == lower_minor + 1 && upper_patch.unwrap_or(0) == 0
856	    );
857	    let upper_bound = if one_minor_window {
858	        format!("{}.{}", target.major()?, target.minor()? + 1)
859	    } else {
860	        (target.major()? + 1).to_string()
861	    };
862	    let rendered = format!(">={},<{upper_bound}", render_target(">=", target)?);
863	    let req = VersionReq::parse(&rendered, Ecosystem::Pypi).ok()?;
864	    Some(DepSpec::Range(req, rendered))
865	}
866	
867	/// Every requirement string of one array as a dependency edge addressed by its index in `container`.
868	fn requirement_entries<'a>(
869	    requirements: &'a toml_edit::Array,
870	    kind: DepKind,
871	    container: &'a DepContainer,
872	) -> impl Iterator<Item = DependencyEntry> + 'a {
873	    requirements.iter().enumerate().filter_map(move |(position, item)| {
874	        let locator = DepLocator::python(container.clone(), Some(position));
875	        pep508_entry(item.as_str()?, kind, locator)
876	    })
877	}
878	
879	/// One PEP 508 requirement string as a dependency edge, or `None` when it names no package.
880	fn pep508_entry(full_req_str: &str, kind: DepKind, locator: DepLocator) -> Option<DependencyEntry> {
881	    // `Requirement::parse` couldn't extract even a package name (an empty string or a
882	    // marker-only fragment): there is no name to key an entry on.
883	    let req = Requirement::parse(full_req_str)?;
884	    let req_str = req.spec.clone().unwrap_or_else(|| "*".to_string());
885	    let parsed_req_str = req.spec.as_deref().unwrap_or(">=0.0.0");
886	    let spec = match VersionReq::parse(parsed_req_str, Ecosystem::Pypi) {
887	        Ok(spec) => DepSpec::Range(spec, req_str),
888	        // A PEP 508 clause `pep440_rs` can't parse (exotic or malformed syntax): keep the
889	        // dependency visible in the graph rather than silently dropping it.
890	        Err(_) => DepSpec::Opaque(req_str),
891	    };
892	    Some(DependencyEntry {
893	        name: req.name.clone(),
894	        package_name: req.name.clone(),
895	        inherited: false,
896	        kind,
897	        spec,
898	        locator,
899	    })
900	}
901	
902	/// The requirement string with `name`'s constraint replaced by `new_spec_str`, or `None` when
903	/// the requirement names another package.
904	fn rewrite_requirement(full_req: &str, name: &str, new_spec_str: &str) -> Option<String> {
905	    let req = Requirement::parse(full_req)?;
906	    if normalize_pypi_package_name(&req.name) != normalize_pypi_package_name(name) {
907	        return None;
908	    }
909	    let formatted_spec = if new_spec_str.starts_with(['<', '>', '=', '!', '~']) {
910	        new_spec_str.to_string()
911	    } else {
912	        format!(">={new_spec_str}")
913	    };
914	    Some(
915	        Requirement {
916	            name: req.name.clone(),
917	            extras: req.extras.clone(),
918	            spec: Some(formatted_spec),
919	            marker: req.marker.clone(),
920	        }
921	        .render(),
922	    )
923	}
