121	/// Computes a fixed group's shared alignment target. `live_members` must already be filtered to ids present in
122	/// `base` (`solve_cascade` drops stale members). The alignment base is a released member's on-disk version (an
123	/// error, not a silent default, if that member is missing from `base`), or else the highest on-disk untagged version.
124	pub fn fixed_group_target(
125	    group: &GroupName,
126	    live_members: &[PackageId],
127	    base: &BTreeMap<PackageId, Version>,
128	    max_sev: Severity,
129	    tags: &TagIndex,
130	    pre: Option<&callisto_model::format::PreState>,
131	) -> Result<Version, GraphError> {
132	    let released: Vec<&PackageId> = live_members.iter().filter(|id| tags.last_tag(id).is_some()).collect();
133	
134	    let (anchor, aligned_base) = if !released.is_empty() {
135	        let anchor = released[0];
136	        let v = base
137	            .get(anchor)
138	            .cloned()
139	            .ok_or_else(|| GraphError::FixedGroupTaggedMemberMissingBase {
140	                group: group.clone(),
141	                member: anchor.clone(),
142	            })?;
143	        (anchor.clone(), v)
144	    } else {
145	        let mut untagged = live_members
146	            .iter()
147	            .filter_map(|id| base.get(id).map(|v| (id.clone(), v.clone())));
148	        let mut best = untagged
149	            .next()
150	            .ok_or_else(|| GraphError::FixedGroupEmpty { group: group.clone() })?;
151	        for (id, v) in untagged {
152	            match Version::compare(&v, &best.1) {
153	                Ok(std::cmp::Ordering::Greater) => best = (id, v),
154	                Ok(_) => {}
155	                Err(_) => {
156	                    return Err(GraphError::GroupGrammarMismatch {
157	                        group: group.clone(),
158	                        members: live_members
159	                            .iter()
160	                            .filter_map(|m| base.get(m).map(|v| (m.clone(), v.clone())))
161	                            .collect(),
162	                    });
163	                }
164	            }
165	        }
166	        best
167	    };
168	
169	    versioned_bump(&anchor, &aligned_base, max_sev, pre)
170	}
