16	/// SemVer versioning arithmetic implementation matching @changesets/cli semantics.
17	pub struct SemVerVersioning;
18	
19	static SEMVER_VERSIONING: SemVerVersioning = SemVerVersioning;
20	
21	/// PEP 440 versioning arithmetic implementation.
22	///
23	/// Bump semantics (deliberate, see the test matrix below):
24	/// - Release segment is `major.minor.patch`, matching SemVer's shape; any
25	///   4th+ segment is dropped by a bump.
26	/// - Epoch (`N!`) has no SemVer analogue -- carries through unchanged.
27	/// - Pre-releases (`aN`/`bN`/`rcN`) and dev-releases (`.devN`) sort
28	///   *before* the final release (PEP 440: `devN < aN < bN < rcN < final`),
29	///   so a bump finalizes them in place like the SemVer prerelease branch:
30	///   `Patch` drops the tag; `Minor`/`Major` advance the next component up
31	///   only when the lower one is already zero.
32	/// - Post-releases (`.postN`) sort *after* the final release (`final <
33	///   .postN`), so the base release is already shipped: a bump increments
34	///   normally (as if no pre/dev/post suffix existed) and drops the post
35	///   segment, rather than continuing the post sequence.
36	/// - Local version labels (`+localsuffix`) are always dropped.
37	pub struct Pep440Versioning;
38	
39	static PEP440_VERSIONING: Pep440Versioning = Pep440Versioning;
40	
41	pub fn versioning_for(grammar: VersionGrammar) -> Option<&'static dyn Versioning> {
42	    match grammar {
43	        VersionGrammar::SemVer => Some(&SEMVER_VERSIONING),
44	        VersionGrammar::Pep440 => Some(&PEP440_VERSIONING),
45	        _ => None,
46	    }
47	}
48	
49	impl Versioning for SemVerVersioning {
50	    fn grammar(&self) -> VersionGrammar {
51	        VersionGrammar::SemVer
52	    }
53	
54	    fn bump(&self, current: &Version, severity: Severity) -> Result<Version, BumpError> {
55	        if current.grammar() != VersionGrammar::SemVer {
56	            return Err(BumpError::NotSemVer {
57	                raw: current.render().to_string(),
58	                grammar: current.grammar(),
59	            });
60	        }
61	
62	        if severity == Severity::None {
63	            return Ok(current.clone());
64	        }
65	
66	        let major = current.major().unwrap_or(0);
67	        let minor = current.minor().unwrap_or(0);
68	        let patch = current.patch().unwrap_or(0);
69	
70	        let overflow = || BumpError::Overflow {
71	            raw: current.render().to_string(),
72	        };
73	
74	        let (new_major, new_minor, new_patch) =
75	            bump_release_triple(major, minor, patch, severity, current.is_prerelease(), overflow)?;
76	
77	        Ok(Version::semver(new_major, new_minor, new_patch))
78	    }
79	
80	    fn bump_prerelease(
81	        &self,
82	        base: &Version,
83	        severity: Severity,
84	        tag: &str,
85	        current: &Version,
86	    ) -> Result<Version, BumpError> {
87	        if severity == Severity::None {
88	            return Ok(current.clone());
89	        }
90	
91	        let release = self.bump(base, severity)?;
92	        let overflow = || BumpError::Overflow {
93	            raw: current.render().to_string(),
94	        };
95	
96	        let mut counter_suffix = None;
97	        if current.is_prerelease() {
98	            let current_raw = current.render();
99	            if let Some((rel_part, pre_part)) = current_raw.split_once('-')
100	                && rel_part == release.render()
101	            {
102	                let dotted_prefix = format!("{tag}.");
103	                counter_suffix = pre_part
104	                    // Dotted form: e.g. "alpha.3" with tag "alpha" → "3"
105	                    .strip_prefix(&dotted_prefix)
106	                    // Undotted form: e.g. "alpha1" with tag "alpha" → "1"
107	                    .or_else(|| pre_part.strip_prefix(tag));
108	            }
109	        }
110	        let counter = next_counter(counter_suffix, overflow)?;
111	
112	        let prerelease_str = format!("{}-{tag}.{counter}", release.render());
113	        let final_version =
114	            Version::parse(&prerelease_str, VersionGrammar::SemVer).map_err(|_err| BumpError::NotSemVer {
115	                raw: prerelease_str,
116	                grammar: VersionGrammar::SemVer,
117	            })?;
118	
119	        Ok(final_version)
120	    }
121	}
122	
123	impl Versioning for Pep440Versioning {
124	    fn grammar(&self) -> VersionGrammar {
125	        VersionGrammar::Pep440
126	    }
127	
128	    fn bump(&self, current: &Version, severity: Severity) -> Result<Version, BumpError> {
129	        if current.grammar() != VersionGrammar::Pep440 {
130	            return Err(BumpError::NotPep440 {
131	                raw: current.render().to_string(),
132	                grammar: current.grammar(),
133	            });
134	        }
135	
136	        if severity == Severity::None {
137	            return Ok(current.clone());
138	        }
139	
140	        let parsed = parse_pep440(current)?;
141	        let epoch = parsed.epoch();
142	        let (major, minor, patch) = release_triple(&parsed);
143	
144	        // Pre-releases and dev-releases both precede the release they're attached
145	        // to, so a bump finalizes them in place rather than continuing forward.
146	        // But a post-release segment (even combined with a dev segment, e.g.
147	        // `1.2.3.post1.dev1`) outranks the final release (PEP 440 ordering:
148	        // dev < pre < release < post), so any version carrying a post segment
149	        // must bump forward normally, same as the post-only case, never
150	        // finalize in place.
151	        let finalize_in_place = !parsed.is_post() && (parsed.is_pre() || parsed.is_dev());
152	
153	        let overflow = || BumpError::Overflow {
154	            raw: current.render().to_string(),
155	        };
156	
157	        let (new_major, new_minor, new_patch) =
158	            bump_release_triple(major, minor, patch, severity, finalize_in_place, overflow)?;
159	
160	        let bumped = pep440_rs::Version::new([new_major, new_minor, new_patch]).with_epoch(epoch);
161	        render_pep440(bumped)
162	    }
163	
164	    fn bump_prerelease(
165	        &self,
166	        base: &Version,
167	        severity: Severity,
168	        tag: &str,
169	        current: &Version,
170	    ) -> Result<Version, BumpError> {
171	        if severity == Severity::None {
172	            return Ok(current.clone());
173	        }
174	
175	        let release = self.bump(base, severity)?;
176	        let release_str = release.render();
177	
178	        // PEP 440 pre-release labels are restricted to alpha/beta/rc; an arbitrary
179	        // caller-supplied tag (e.g. "next") has no PEP 440 equivalent, so it falls
180	        // back to a dev-release, the closest "not yet final" concept PEP 440 has.
181	        let letter = pep440_prerelease_letter(tag);
182	
183	        let overflow = || BumpError::Overflow {
184	            raw: current.render().to_string(),
185	        };
186	        let current_raw = current.render();
187	        let counter_suffix = current_raw.strip_prefix(release_str).and_then(|rest| match letter {
188	            Some(letter) => rest.strip_prefix(letter),
189	            None => rest.strip_prefix(".dev"),
190	        });
191	        let counter = next_counter(counter_suffix, overflow)?;
192	
193	        let prerelease_str = match letter {
194	            Some(letter) => format!("{release_str}{letter}{counter}"),
195	            None => format!("{release_str}.dev{counter}"),
196	        };
197	
198	        Version::parse(&prerelease_str, VersionGrammar::Pep440).map_err(|e| BumpError::ComputedVersionInvalid {
199	            raw: prerelease_str,
200	            message: e.message,
201	        })
202	    }
203	}
204	
205	/// Maps common pre-release tag spellings to their PEP 440 letter. PEP 440 only
206	/// recognizes alpha/beta/rc pre-releases; anything else has no direct mapping.
207	fn pep440_prerelease_letter(tag: &str) -> Option<&'static str> {
208	    match tag.to_ascii_lowercase().as_str() {
209	        "a" | "alpha" => Some("a"),
210	        "b" | "beta" => Some("b"),
211	        "rc" | "c" | "pre" | "preview" => Some("rc"),
212	        _ => None,
213	    }
214	}
