        assert_eq!(bump_version(&v, Severity::Minor).unwrap().render(), "0.1.0");
        let v = Version::parse("0.0.0", VersionGrammar::SemVer).unwrap();
        assert_eq!(bump_version(&v, Severity::Major).unwrap().render(), "1.0.0");
