1	//! Callisto's single disk-write primitive.
2	//!
3	//! This lives in Layer 1 (`callisto-model`) rather than alongside the manifest
4	//! editors because durable file replacement is not a manifest concern: the
5	//! changelog writer, the pre-mode state file, and the config scaffolder all
6	//! need it too. Hosting it here means those callers do not have to take a
7	//! dependency on `callisto-manifests` purely to reach the filesystem.
8	
9	use std::io::{self, Write};
10	use std::path::Path;
11	
12	use crate::ApplyPermit;
13	use tempfile::NamedTempFile;
14	
15	/// Durably replaces `path`'s contents with `content`.
16	///
17	/// The [`ApplyPermit`] is unused at runtime and exists purely as a compile-time
18	/// obligation: this is callisto's single disk-write primitive, so requiring a
19	/// permit here means no code path can reach the filesystem without having first
20	/// consulted the dry-run flag. See [`crate::permit`].
21	///
22	/// # Errors
23	///
24	/// Returns the first I/O error encountered: creating parent directories, writing the temp file,
25	/// flushing, fsyncing, persisting (renaming) to `path`, or syncing the directory that holds it.
26	pub fn atomic_write(path: &Path, content: &str, permit: &ApplyPermit) -> io::Result<()> {
27	    write_durably(path, content, true, permit)
28	}
29	
30	/// [`atomic_write`] that never replaces: it fails with `AlreadyExists` if anything is at `path` when the file is put in
31	/// place, including a file created by another process after this call began. The content is durable before it appears.
32	///
33	/// # Errors
34	///
35	/// `AlreadyExists` when `path` is taken, otherwise the same errors as [`atomic_write`].
36	pub fn atomic_write_new(path: &Path, content: &str, permit: &ApplyPermit) -> io::Result<()> {
37	    write_durably(path, content, false, permit)
38	}
39	
40	fn write_durably(path: &Path, content: &str, replace: bool, permit: &ApplyPermit) -> io::Result<()> {
41	    let _permit = permit;
42	    let raw_parent = path.parent().unwrap_or_else(|| Path::new("."));
43	    let parent = if raw_parent.as_os_str().is_empty() {
44	        Path::new(".")
45	    } else {
46	        raw_parent
47	    };
48	    let created_parent = !parent.try_exists()?;
49	    std::fs::create_dir_all(parent)?;
50	
51	    let mut temp = temp_file_in(parent)?;
52	    if replace {
53	        match_existing_mode(temp.as_file(), path)?;
54	    }
55	    temp.write_all(content.as_bytes())?;
56	    temp.flush()?;
57	    temp.as_file().sync_all()?;
58	    if replace {
59	        temp.persist(path).map_err(|e| e.error)?;
60	    } else {
61	        temp.persist_noclobber(path).map_err(|e| e.error)?;
62	    }
63	
64	    sync_directory(parent)?;
65	    // A directory this call created is itself a new entry in its parent.
66	    if created_parent && let Some(grandparent) = parent.parent().filter(|dir| !dir.as_os_str().is_empty()) {
67	        sync_directory(grandparent)?;
68	    }
69	    Ok(())
70	}
