72	/// A temp file whose mode follows the process umask like any new file, instead of `tempfile`'s owner-only `0600`.
73	fn temp_file_in(dir: &Path) -> io::Result<NamedTempFile> {
74	    #[cfg(unix)]
75	    {
76	        use std::os::unix::fs::PermissionsExt;
77	        tempfile::Builder::new()
78	            .permissions(std::fs::Permissions::from_mode(0o666))
79	            .tempfile_in(dir)
80	    }
81	    #[cfg(not(unix))]
82	    {
83	        NamedTempFile::new_in(dir)
84	    }
85	}
