87	/// Gives the temp file the mode of the file it replaces; a new file keeps the umask-derived mode.
88	fn match_existing_mode(temp: &std::fs::File, target: &Path) -> io::Result<()> {
89	    #[cfg(unix)]
90	    {
91	        use std::os::unix::fs::PermissionsExt;
92	        match std::fs::metadata(target) {
93	            Ok(existing) => {
94	                temp.set_permissions(std::fs::Permissions::from_mode(existing.permissions().mode() & 0o7777))
95	            }
96	            Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(()),
97	            Err(error) => Err(error),
98	        }
99	    }
100	    #[cfg(not(unix))]
101	    {
102	        let _ = (temp, target);
103	        Ok(())
104	    }
105	}
