107	/// Flushes `dir`'s entries so a rename survives power loss. A directory that may not be opened for reading (a `-wx`
108	/// mode, `PermissionDenied`) or a filesystem that cannot sync one (`Unsupported`, `InvalidInput`, macOS `ENOTSUP`) is
109	/// skipped: the file is already in place and failing the command now would misreport a write that happened. Any other
110	/// failure, whether opening or syncing, an I/O error above all, means the rename may not be durable and is reported.
111	fn sync_directory(dir: &Path) -> io::Result<()> {
112	    #[cfg(unix)]
113	    {
114	        let handle = match std::fs::File::open(dir) {
115	            Ok(handle) => handle,
116	            Err(error) if error.kind() == io::ErrorKind::PermissionDenied || sync_unsupported(&error) => {
117	                return Ok(());
118	            }
119	            Err(error) => return Err(error),
120	        };
121	        match handle.sync_all() {
122	            Err(error) if sync_unsupported(&error) => Ok(()),
123	            result => result,
124	        }
125	    }
126	    #[cfg(not(unix))]
127	    {
128	        let _ = dir;
129	        Ok(())
130	    }
131	}
