133	/// Fails now if [`atomic_write`] to `path` could not succeed, leaving nothing behind: no file and no directory.
134	/// A pre-existing regular file at `path` is accepted because the write replaces it. When the parent directory does not
135	/// exist yet, the nearest one that does must take a new file, which is what creating the missing ones needs.
136	///
137	/// # Errors
138	///
139	/// Returns the I/O error creating a temp file beside `path` (or in its nearest existing parent), or
140	/// `IsADirectory`-style `InvalidInput` when `path` is a directory or a parent is not.
141	pub fn probe_atomic_write(path: &Path, permit: &ApplyPermit) -> io::Result<()> {
142	    let _permit = permit;
143	    if path.is_dir() {
144	        return Err(io::Error::new(
145	            io::ErrorKind::InvalidInput,
146	            "destination is a directory",
147	        ));
148	    }
149	    let raw_parent = path.parent().unwrap_or_else(|| Path::new("."));
150	    let parent = if raw_parent.as_os_str().is_empty() {
151	        Path::new(".")
152	    } else {
153	        raw_parent
154	    };
155	    let existing = parent
156	        .ancestors()
157	        .find(|ancestor| ancestor.try_exists().unwrap_or(false))
158	        .unwrap_or_else(|| Path::new("."));
159	    if !existing.is_dir() {
160	        return Err(io::Error::new(
161	            io::ErrorKind::InvalidInput,
162	            "a parent of the destination is not a directory",
163	        ));
164	    }
165	    NamedTempFile::new_in(existing)?;
166	    sync_directory(existing)
167	}
