58	    /// Spec: concurrent `atomic_write` calls targeting the same path from
59	    /// multiple threads must not corrupt the file. The last writer wins
60	    /// (last-write-wins semantics), but the file must exist after all threads
61	    /// finish and its content must be exactly one complete, untruncated write
62	    /// -- never an interleaved mix of bytes from two concurrent writes.
63	    ///
64	    /// `atomic_write` achieves this by writing to a fresh `NamedTempFile` and
65	    /// then atomically renaming it into place, which is guaranteed to be an
66	    /// atomic replace on POSIX filesystems.
67	    #[test]
68	    fn concurrent_atomic_write_to_same_path_does_not_corrupt_file() {
69	        let dir = tempdir().unwrap();
70	        let target = std::sync::Arc::new(dir.path().join("shared.txt"));
71	
72	        const THREAD_COUNT: usize = 10;
73	        let permit = std::sync::Arc::new(ApplyPermit::force_for_tests());
74	
75	        let handles: Vec<_> = (0..THREAD_COUNT)
76	            .map(|i| {
77	                let path = std::sync::Arc::clone(&target);
78	                let p = std::sync::Arc::clone(&permit);
79	                std::thread::spawn(move || {
80	                    let content = format!("thread-{i}\n");
81	                    atomic_write(&path, &content, &p).expect("atomic_write must not fail");
82	                })
83	            })
84	            .collect();
85	
86	        for handle in handles {
87	            handle.join().expect("thread must not panic");
88	        }
89	
90	        // The file must exist.
91	        assert!(target.exists(), "file must exist after all threads finish");
92	
93	        // The file must contain exactly one complete thread's content.
94	        let final_content = std::fs::read_to_string(target.as_ref()).unwrap();
95	        assert!(
96	            !final_content.is_empty(),
97	            "file content must not be empty after concurrent writes"
98	        );
99	        assert!(
100	            (0..THREAD_COUNT).any(|i| final_content == format!("thread-{i}\n")),
101	            "file content must be exactly one valid thread write, got: {:?}",
102	            final_content
103	        );
104	    }
