6	use crate::changelog::ChangelogError;
7	
8	/// Prepend a rendered changelog entry for `display_name` to the
9	/// changelog file at `changelog_path` (relative to `root`).
10	///
11	/// # Concurrency
12	///
13	/// **Not safe for concurrent calls on the same `path`.** Reads existing
14	/// content then writes atomically, but a second concurrent call could
15	/// read stale content between those two points. Callers must ensure
16	/// sequential access per changelog file -- if this ever moves to
17	/// parallel `apply`, add a per-path lock before removing this note.
18	pub fn prepend(
19	    root: &Path,
20	    changelog_path: &Path,
21	    display_name: &str,
22	    rendered: &str,
23	    permit: &ApplyPermit,
24	) -> Result<(), ChangelogError> {
25	    let full_path = root.join(changelog_path);
26	    if let Some(parent) = full_path.parent() {
27	        fs::create_dir_all(parent).map_err(|e| ChangelogError::WriteFailed {
28	            path: changelog_path.to_path_buf(),
29	            message: e.to_string(),
30	        })?;
31	    }
32	
33	    let existing = callisto_model::strict_fs::read_optional(&full_path)
34	        .map_err(|e| ChangelogError::ReadFailed {
35	            path: changelog_path.to_path_buf(),
36	            message: e.to_string(),
37	        })?
38	        .unwrap_or_else(|| format!("# {display_name}\n\n"));
39	
40	    // Normalise CRLF → LF so the prefix patterns always match, then restore
41	    // the original line endings on the way out if the file used CRLF.
42	    let had_crlf = existing.contains("\r\n");
43	    let (bom, existing) = match existing.strip_prefix('\u{feff}') {
44	        Some(rest) => ("\u{feff}", rest),
45	        None => ("", existing.as_str()),
46	    };
47	    let normalised = if had_crlf {
48	        existing.replace("\r\n", "\n")
49	    } else {
50	        existing.to_owned()
51	    };
52	
53	    // Bug 8 guard: if the version heading we are about to insert already exists
54	    // in the file, skip the write entirely (idempotent behaviour). The heading
55	    // is the first line of `rendered` (e.g. "## 1.0.0").
56	    let version_heading = rendered.lines().next().unwrap_or("").trim();
57	    if !version_heading.is_empty() && normalised.lines().any(|l| l.trim() == version_heading) {
58	        return Ok(());
59	    }
60	
61	    // All three header shapes (blank line after the H1, no blank line, or no
62	    // matching H1 at all -- e.g. a casing change, HTML anchor, or package
63	    // rename) splice the new entry in identically; only what counts as
64	    // "the rest of the file to keep" differs, so compute just that here.
65	    let rest: &str = if let Some(rest) = normalised.strip_prefix(&format!("# {display_name}\n\n")) {
66	        rest
67	    } else if let Some(rest) = normalised.strip_prefix(&format!("# {display_name}\n")) {
68	        rest
69	    } else {
70	        // No matching H1 found: emit the correct H1 first so the output is
71	        // well-formed, keeping the entire existing content as the body.
72	        &normalised
73	    };
74	
75	    let mut new_content = String::from(bom);
76	    new_content.push_str(&format!("# {display_name}\n\n"));
77	    new_content.push_str(rendered);
78	    if !rendered.ends_with('\n') {
79	        new_content.push('\n');
80	    }
81	    new_content.push('\n');
82	    new_content.push_str(rest);
83	
84	    if had_crlf {
85	        new_content = new_content.replace('\n', "\r\n");
86	    }
87	
88	    callisto_model::atomic::atomic_write(&full_path, &new_content, permit).map_err(|e| ChangelogError::WriteFailed {
89	        path: changelog_path.to_path_buf(),
90	        message: e.to_string(),
91	    })
92	}
