94	/// The non-empty `## {version}` section body, trimmed.
95	pub fn extract_section<'a>(changelog: &'a str, version: &Version) -> Option<&'a str> {
96	    find_section(changelog, version).filter(|section| !section.is_empty())
97	}
98	
99	/// The trimmed `## {version}` section body, empty when the heading has no content;
100	/// `None` only when the heading is absent.
101	pub fn find_section<'a>(changelog: &'a str, version: &Version) -> Option<&'a str> {
102	    let target_heading = format!("## {}", version.render());
103	    let mut start_byte = None;
104	
105	    let mut offset = 0;
106	    for line in changelog.split_inclusive('\n') {
107	        let trimmed = line.trim_end();
108	        if trimmed == target_heading {
109	            start_byte = Some(offset + line.len());
110	            break;
111	        }
112	        offset += line.len();
113	    }
114	
115	    let start = start_byte?;
116	    let slice_after = &changelog[start.min(changelog.len())..];
117	
118	    let mut end = slice_after.len();
119	    let mut line_offset = 0;
120	    let mut fence: Option<(char, usize)> = None;
121	
122	    for line in slice_after.split_inclusive('\n') {
123	        let content = line.trim_start();
124	        let inside_fence = fence.is_some();
125	        fence = match fence {
126	            None => fence_opening(strip_list_marker(content)),
127	            Some((marker, length)) if closes_fence(content, marker, length) => None,
128	            open => open,
129	        };
130	        // The sections Callisto writes start at column 0; a heading-like line in a summary is indented under its bullet.
131	        let heading = line.starts_with("## ") || line.starts_with("# ");
132	        if line_offset > 0 && !inside_fence && heading {
133	            end = line_offset;
134	            break;
135	        }
136	        line_offset += line.len();
137	    }
138	
139	    Some(slice_after[..end.min(slice_after.len())].trim())
140	}
