142	/// `text` without a leading list marker (`-`, `*`, `+`, `1.` or `1)`), so a fence opened on a bullet's first line is seen.
143	fn strip_list_marker(text: &str) -> &str {
144	    for marker in ["- ", "* ", "+ "] {
145	        if let Some(rest) = text.strip_prefix(marker) {
146	            return rest.trim_start();
147	        }
148	    }
149	    let after_digits = text.trim_start_matches(|c: char| c.is_ascii_digit());
150	    if after_digits.len() < text.len() && (after_digits.starts_with(". ") || after_digits.starts_with(") ")) {
151	        return after_digits[2..].trim_start();
152	    }
153	    text
154	}
