156	/// The marker character and length of a fence that `text` opens (three or more backticks or tildes).
157	fn fence_opening(text: &str) -> Option<(char, usize)> {
158	    let marker = text.chars().next().filter(|c| matches!(c, '`' | '~'))?;
159	    let length = text.chars().take_while(|c| *c == marker).count();
160	    (length >= 3).then_some((marker, length))
161	}
