163	/// Whether `text` closes a fence opened with `length` of `marker`: the same character, at least as many, nothing else.
164	fn closes_fence(text: &str, marker: char, length: usize) -> bool {
165	    let run = text.chars().take_while(|c| *c == marker).count();
166	    run >= length && text[run..].trim().is_empty()
167	}
