142	    let rendered: Vec<String> = paths.iter().map(|path| path.to_string_lossy().into_owned()).collect();
143	    let mut args = vec!["check-ignore", "--"];
144	    args.extend(rendered.iter().map(String::as_str));
145	    let output = runner.run("git", &args, root)?;
146	    match output.exit_code {
147	        Some(0) => Ok(!output.stdout.trim().is_empty()),
148	        Some(1) => Ok(false),
149	        exit_code => Err(GraphError::Command(CommandError::Failed {
150	            program: "git".to_string(),
151	            exit_code,
152	            stderr: output.redacted_stderr(),
153	        })),
154	    }
155	}
