14	/// What a plan does to a path, which decides what must hold for it.
15	#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
16	enum Target {
17	    /// A manifest the plan edits: it must exist as a readable regular file and its directory must take a new file.
18	    Existing,
19	    /// A file the plan may create or replace, such as a changelog or `pre.json`.
20	    Creatable,
21	    /// A file the plan deletes: only the path itself is checked.
22	    Removed,
23	}
24	
25	/// Every path `plan` writes or deletes under `opts`, once each.
26	fn targets(plan: &VersionPlan, opts: &ApplyOptions) -> BTreeSet<(PathBuf, Target)> {
27	    let mut targets = BTreeSet::new();
28	    for bump in &plan.bumps {
29	        for write in &bump.writes {
30	            let path = match write {
31	                VersionWriteTarget::Manifest(path) => path,
32	                VersionWriteTarget::CargoWorkspacePackage { root_manifest } => root_manifest,
33	            };
34	            targets.insert((path.clone(), Target::Existing));
35	        }
36	    }
37	    for rewrite in &plan.rewrites {
38	        let path = match &rewrite.key.target {
39	            DepWriteTarget::Manifest(path) => path,
40	            DepWriteTarget::CargoWorkspaceDependency { root_manifest } => root_manifest,
41	        };
42	        targets.insert((path.clone(), Target::Existing));
43	    }
44	    targets.extend(
45	        plan.platform_writes
46	            .iter()
47	            .map(|write| (write.manifest.clone(), Target::Existing)),
48	    );
49	    targets.extend(
50	        plan.optional_dep_updates
51	            .iter()
52	            .map(|update| (update.manifest.clone(), Target::Existing)),
53	    );
54	    if !opts.transient {
55	        targets.extend(
56	            plan.changelog_writes
57	                .iter()
58	                .map(|write| (write.changelog_path.clone(), Target::Creatable)),
59	        );
60	        targets.extend(
61	            plan.consumed_changesets
62	                .iter()
63	                .map(|path| (path.clone(), Target::Removed)),
64	        );
65	        if plan.pre_state_update.is_some() {
66	            targets.insert((plan.pre_json_path.clone(), Target::Creatable));
67	        } else if let Some(path) = &plan.delete_pre_json {
68	            targets.insert((path.clone(), Target::Removed));
69	        }
70	    }
71	    targets
72	}
73	
74	/// Fails with every target that cannot be written, before anything is.
75	///
76	/// # Errors
77	///
78	/// [`GraphError::ApplyPreflight`] naming each unwritable path and why.
79	pub(super) fn check<R: CommandRunner>(
80	    root: &Path,
81	    plan: &VersionPlan,
82	    opts: &ApplyOptions,
83	    permit: &ApplyPermit,
84	    runner: &R,
85	) -> Result<(), GraphError> {
86	    let targets = targets(plan, opts);
87	    let mut problems: Vec<String> = targets
88	        .iter()
89	        .filter_map(|(path, target)| {
90	            problem(root, path, *target, permit).map(|reason| format!("`{}`: {reason}", path.display()))
91	        })
92	        .collect();
93	    if !opts.transient {
94	        let staged: Vec<PathBuf> = targets
95	            .iter()
96	            .filter(|(_, target)| *target != Target::Removed)
97	            .map(|(path, _)| path.clone())
98	            .collect();
99	        problems.extend(ignored_paths(runner, root, &staged)?.into_iter().map(|path| {
100	            format!(
101	                "`{}`: is ignored by a .gitignore, so Git would not stage it",
102	                path.display()
103	            )
104	        }));
105	    }
106	    if problems.is_empty() {
107	        Ok(())
108	    } else {
109	        Err(GraphError::ApplyPreflight { problems })
110	    }
111	}
112	
113	/// The paths of `paths` that a `.gitignore` ignores and Git does not already track, which `git add` refuses.
114	///
115	/// # Errors
116	///
117	/// `git check-ignore` could not run or failed (anything but "some ignored" and "none ignored").
118	pub(super) fn ignored_paths<R: CommandRunner>(
119	    runner: &R,
120	    root: &Path,
121	    paths: &[PathBuf],
122	) -> Result<BTreeSet<PathBuf>, GraphError> {
123	    if paths.is_empty() {
124	        return Ok(BTreeSet::new());
125	    }
126	    // One quiet run answers the usual "none ignored"; only when something is does each path get asked, so no output
127	    // needs parsing (git quotes unusual names).
128	    if !any_ignored(runner, root, paths)? {
129	        return Ok(BTreeSet::new());
130	    }
131	    let mut ignored = BTreeSet::new();
132	    for path in paths {
133	        if any_ignored(runner, root, std::slice::from_ref(path))? {
134	            ignored.insert(path.clone());
135	        }
136	    }
137	    Ok(ignored)
138	}
139	
