171	/// The advisory for a tag a package matched by name but did not make.
172	fn foreign_tag_diagnostic(id: &PackageId, tag: &str) -> Diagnostic {
173	    Diagnostic {
174	        code: DiagnosticCode::TagOwnedByAnotherPackage,
175	        severity: DiagnosticSeverity::Info,
176	        message: format!(
177	            "tag `{tag}` was made when `{name}` named a manifest of another ecosystem, so `{id}` does not take it; if \
178	             this package was renamed, set `previous-tag-templates` on its `[[package]]` rule",
179	            name = id.name(),
180	            id = id.display_name(),
181	        ),
182	        package: Some(id.clone()),
183	        path: None,
184	        escalated_by: None,
185	        governed_by: None,
186	    }
187	}
