use std::collections::BTreeMap;

use callisto_model::vcs::GitAccess;
use callisto_model::{
    select_last_tag, CommitSha, Diagnostic, DiagnosticCode, DiagnosticSeverity, LastTag, LastTagSelection, PackageId,
    TagTemplate, VersionGrammar,
};

use crate::config::ResolvedConfig;
use crate::error::GraphError;
use crate::resolver::DependencyResolver;
use crate::IdentityIndex;

/// Fetches the full, unfiltered list of every tag name in the repository.
///
/// Deliberately fetches with no glob pattern: callers filter afterwards via
/// [`matching_tags`], so the fetch batches once across every package (see
/// [`TagIndex::build`]) instead of one `git` spawn per package.
pub(crate) fn fetch_all_tags(git: &GitAccess<'_>) -> Result<Vec<String>, GraphError> {
    let tags = git.list_tags(None)?;
    Ok(tags.into_iter().map(|t| t.as_str().to_string()).collect())
}

/// Tag names in byte order. The tags beginning with a literal prefix are one contiguous run, found by binary search, so
/// matching a template against them does not test every tag in the repository.
struct SortedTags<'a>(Vec<&'a str>);

impl<'a> SortedTags<'a> {
    fn new(tags: &'a [String]) -> Self {
        let mut sorted: Vec<&str> = tags.iter().map(String::as_str).collect();
        sorted.sort_unstable();
        SortedTags(sorted)
    }

    fn starting_with(&self, prefix: &str) -> &[&'a str] {
        let start = self.0.partition_point(|tag| *tag < prefix);
        let run = self.0[start..].iter().take_while(|tag| tag.starts_with(prefix)).count();
        &self.0[start..start + run]
    }
}

/// Filters `all_tags` down to those matching `template`'s glob.
///
/// Compiles the glob via [`callisto_model::vcs::compile_tag_glob`] -- the same
/// helper `GitAccess::list_tags` uses -- so tag selection is identical
/// either way. Includes error behavior: a
/// `template.glob()` that fails to compile surfaces as
/// `Err(GraphError::Vcs(VcsError::InvalidGlob))` -- matching every tag is
/// the unsafe alternative, since a malformed template must never silently
/// make "last tag" resolution pick an unrelated package's tag.
fn matching_tags<'a>(all_tags: &SortedTags<'a>, template: &TagTemplate) -> Result<Vec<&'a str>, GraphError> {
    let glob = template.glob();
    GLOB_COMPILE_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    let matcher = callisto_model::vcs::compile_tag_glob(&glob).map_err(GraphError::Vcs)?;

    // A match must begin with the glob's literal text before its first wildcard, so only that run is tested.
    let literal = glob
        .split(['*', '?', '[', ']', '{', '}', '\\'])
        .next()
        .unwrap_or_default();
    Ok(all_tags
        .starting_with(literal)
        .iter()
        .copied()
        .filter(|tag| matcher.is_match(tag))
        .collect())
}

/// Test-observability counter: total number of times [`matching_tags`] has
/// compiled a fresh `globset::Glob`. Production code never reads this; it
/// exists so tests can assert `TagIndex::build` compiles/scans at most once
/// per *distinct* tag-template glob, not once per package -- a
/// `[[package-set]]` rule with a fixed (non-`{name}`) `tag-template` can
/// apply the identical template string to many packages at once.
static GLOB_COMPILE_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// Resets the internal glob-compile call counter to zero. Intended for use in test setup.
///
/// Process-global, like `callisto_manifests::reset_open_call_count` -- exact
/// counts must be asserted from an isolated integration-test binary under
/// `#[serial]`, not an inline unit test sharing this crate's `--lib`
/// process with other, non-serial tests (see
/// `tests/tag_glob_cache_count_test.rs`).
pub fn reset_glob_compile_count() {
    GLOB_COMPILE_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
}

/// Reads the current value of the internal glob-compile call counter.
pub fn glob_compile_count() -> usize {
    GLOB_COMPILE_COUNT.load(std::sync::atomic::Ordering::SeqCst)
}

/// Selects the highest-versioned tag matching `template` out of a full tag
/// list previously obtained via [`fetch_all_tags`], reusing a `cache` of
/// already-compiled/already-scanned candidates keyed by `template.glob()`
/// -- a `[[package-set]]` rule with a fixed (non-`{name}`) `tag-template`
/// string applies the identical template to every matching package, so
/// without this cache `TagIndex::build`'s per-package loop would recompile
/// the same `globset::Glob` and rescan the full tag list once per package
/// sharing that template, instead of once per distinct template.
fn select_from_tags_cached<'a>(
    all_tags: &SortedTags<'a>,
    template: &TagTemplate,
    grammar: VersionGrammar,
    cache: &mut std::collections::HashMap<String, Vec<&'a str>>,
) -> Result<LastTagSelection, GraphError> {
    let candidates = candidates_cached(all_tags, template, cache)?;
    select_last_tag(template, grammar, candidates).map_err(GraphError::from)
}

/// The tags matching `template`, scanned once per distinct glob.
fn candidates_cached<'a>(
    all_tags: &SortedTags<'a>,
    template: &TagTemplate,
    cache: &mut std::collections::HashMap<String, Vec<&'a str>>,
) -> Result<Vec<&'a str>, GraphError> {
    let glob = template.glob();
    if let Some(cached) = cache.get(&glob) {
        return Ok(cached.clone());
    }
    let matched = matching_tags(all_tags, template)?;
    cache.insert(glob, matched.clone());
    Ok(matched)
}

/// Keeps the chosen tag and records each skipped-tag warning once, however many packages scan the same tags.
fn take_chosen(selection: LastTagSelection, diagnostics: &mut Vec<Diagnostic>) -> Option<LastTag> {
    for diagnostic in selection.skipped {
        if !diagnostics.iter().any(|seen| seen.message == diagnostic.message) {
            diagnostics.push(diagnostic);
        }
    }
    selection.chosen
}

/// The higher-versioned of two tags found for one package; `first` wins a tie.
fn newest(first: Option<LastTag>, second: Option<LastTag>) -> Option<LastTag> {
    match (first, second) {
        (Some(first), Some(second)) => {
            let newer = second
                .version
                .compare(&first.version)
                .is_ok_and(std::cmp::Ordering::is_gt);
            Some(if newer { second } else { first })
        }
        (first, second) => first.or(second),
    }
}

/// E101 when a package's default template (`{name}@{version}`) is also another package's template.
fn reject_shared_default_templates<D: DependencyResolver>(graph: &D) -> Result<(), GraphError> {
    let mut by_template: BTreeMap<String, (bool, Vec<PackageId>)> = BTreeMap::new();
    for pkg in graph.packages() {
        let tmpl = pkg
            .tag_template
            .clone()
            .unwrap_or_else(|| TagTemplate::default_for(&pkg.id));
        let (has_default, ids) = by_template.entry(tmpl.as_str()).or_default();
        *has_default |= pkg.tag_template.is_none();
        ids.push(pkg.id.clone());
    }
    match by_template
        .into_iter()
        .find(|(_, (has_default, ids))| *has_default && ids.len() > 1)
    {
        Some((template, (_, packages))) => Err(GraphError::SharedDefaultTagTemplate { template, packages }),
        None => Ok(()),
    }
}

/// The advisory for a tag a package matched by name but did not make.
fn foreign_tag_diagnostic(id: &PackageId, tag: &str) -> Diagnostic {
    Diagnostic {
        code: DiagnosticCode::TagOwnedByAnotherPackage,
        severity: DiagnosticSeverity::Info,
        message: format!(
            "tag `{tag}` was made when `{name}` named a manifest of another ecosystem, so `{id}` does not take it; if \
             this package was renamed, set `previous-tag-templates` on its `[[package]]` rule",
            name = id.name(),
            id = id.display_name(),
        ),
        package: Some(id.clone()),
        path: None,
        escalated_by: None,
        governed_by: None,
    }
}

pub struct TagIndex {
    last: BTreeMap<PackageId, Option<LastTag>>,
    templates: BTreeMap<PackageId, TagTemplate>,
    pre_cursor: BTreeMap<PackageId, Option<CommitSha>>,
    /// Tags that match a package's default template by name but were made by another package.
    foreign: BTreeMap<PackageId, std::collections::BTreeSet<String>>,
    /// The full, unfiltered raw tag list fetched once during `build` (see
    /// `fetch_all_tags`), kept around so callers checking whether a specific
    /// tag name already exists (e.g. the unreleased-version check, once per
    /// package) can consult this in-memory set instead of re-querying `git`
    /// once per check.
    all_tags: std::collections::BTreeSet<String>,
    /// The commit each tag ends at, read with one `git for-each-ref` the first time a caller asks for any.
    commits: std::cell::OnceCell<BTreeMap<String, CommitSha>>,
    pub diagnostics: Vec<Diagnostic>,
}

impl TagIndex {
    pub fn build<D: DependencyResolver>(
        git: &GitAccess<'_>,
        graph: &D,
        identity: &IdentityIndex,
        cfg: &ResolvedConfig,
    ) -> Result<Self, GraphError> {
        reject_shared_default_templates(graph)?;
        let mut last = BTreeMap::new();
        let mut templates = BTreeMap::new();
        let mut pre_cursor = BTreeMap::new();
        let mut foreign: BTreeMap<PackageId, std::collections::BTreeSet<String>> = BTreeMap::new();
        let mut diagnostics = Vec::new();

        // Fetch the raw tag list exactly once for the whole build, not once
        // per package -- see `fetch_all_tags` for why.
        let all_tag_names = fetch_all_tags(git)?;
        let all_tags_set: std::collections::BTreeSet<String> = all_tag_names.iter().cloned().collect();
        let all_tags = SortedTags::new(&all_tag_names);
        let mut glob_cache: std::collections::HashMap<String, Vec<&str>> = std::collections::HashMap::new();

        let mut rosters = crate::history::Rosters::default();
        // The first candidate of every bare-named package is checked below; read their manifests together.
        let mut wanted = Vec::new();
        for pkg in graph.packages() {
            if pkg.tag_template.is_some() || pkg.id.ecosystem().is_some() {
                continue;
            }
            let (Some(manifest), Ok(grammar)) = (pkg.canonical_manifests().next(), pkg.version_grammar()) else {
                continue;
            };
            let tmpl = TagTemplate::default_for(&pkg.id);
            let Ok(candidates) = candidates_cached(&all_tags, &tmpl, &mut glob_cache) else {
                continue;
            };
            let Ok(selection) = select_last_tag(&tmpl, grammar, candidates.iter().copied()) else {
                continue;
            };
            if let Some(tag) = take_chosen(selection, &mut Vec::new()) {
                wanted.push((tag.name.as_str().to_owned(), manifest.path.clone()));
            }
        }
        rosters.prefetch(git, &wanted);

        for pkg in graph.packages() {
            // `TagTemplate::default_for` is the single source of truth for a
            // package's default tag template -- matches `release.rs`'s own
            // `unwrap_or_else(|| callisto_model::TagTemplate::default_for(&package.id))`.
            // Deliberately not `TagTemplate::parse(&format!("{name}@{{version}}"))`:
            // `parse` additionally validates git-ref-name legality, which
            // `default_for` does not, so the two could previously reject/accept a
            // package name differently. Using `default_for` here removes that
            // extra validation from this call site to align with the
            // already-shipped `release.rs` behavior.
            let tmpl = pkg
                .tag_template
                .clone()
                .unwrap_or_else(|| TagTemplate::default_for(&pkg.id));
            let grammar = pkg.version_grammar()?;
            let mut chosen = if pkg.tag_template.is_none() && pkg.id.ecosystem().is_none() {
                // A bare name is the only evidence the default template has, so a tag is the package's only if its
                // commit did not hold the name in another ecosystem.
                let mut candidates = candidates_cached(&all_tags, &tmpl, &mut glob_cache)?;
                loop {
                    let selection = select_last_tag(&tmpl, grammar, candidates.iter().copied())?;
                    let Some(tag) = take_chosen(selection, &mut diagnostics) else {
                        break None;
                    };
                    // History that cannot be read is no evidence of another owner.
                    let held = crate::history::may_have_held_name_at(
                        git,
                        tag.name.as_str(),
                        pkg.id.name(),
                        pkg,
                        identity,
                        &mut rosters,
                    )
                    .unwrap_or(true);
                    if held {
                        break Some(tag);
                    }
                    diagnostics.push(foreign_tag_diagnostic(&pkg.id, tag.name.as_str()));
                    foreign
                        .entry(pkg.id.clone())
                        .or_default()
                        .insert(tag.name.as_str().to_string());
                    candidates.retain(|candidate| *candidate != tag.name.as_str());
                }
            } else {
                take_chosen(
                    select_from_tags_cached(&all_tags, &tmpl, grammar, &mut glob_cache)?,
                    &mut diagnostics,
                )
            };
            if chosen.is_none() {
                let native_names: Vec<_> = identity.native_names(&pkg.id).collect();
                if let Some(previous) = crate::config::resolve::resolve_package_config(&native_names, cfg)
                    .map(|package_config| package_config.previous_tag_templates.as_slice())
                {
                    for template in previous {
                        chosen = take_chosen(
                            select_from_tags_cached(&all_tags, template, grammar, &mut glob_cache)?,
                            &mut diagnostics,
                        );
                        if chosen.is_some() {
                            break;
                        }
                    }
                }
            }
            if chosen.is_none() && pkg.tag_template.is_none() && pkg.id.ecosystem().is_some() {
                // A promoted package keeps the `{name}@` tags it made while its name was unique.
                let unqualified = TagTemplate::default_for(&PackageId::Bare(pkg.id.name().to_string()));
                let same: Vec<&callisto_model::Package> = graph
                    .packages()
                    .filter(|p| p.id.ecosystem().is_some() && p.id.name() == pkg.id.name())
                    .collect();
                let mut owned = Vec::new();
                for tag in matching_tags(&all_tags, &unqualified)? {
                    if crate::history::sole_owner_at(git, tag, pkg.id.name(), &same, identity, &mut rosters)?
                        .is_some_and(|owner| owner.id == pkg.id)
                    {
                        owned.push(tag);
                    }
                }
                chosen = take_chosen(
                    select_last_tag(&unqualified, grammar, owned).map_err(GraphError::from)?,
                    &mut diagnostics,
                );
            }
            if pkg.tag_template.is_none() && pkg.id.ecosystem().is_none() {
                // A demoted package keeps the qualified tags it made while its name was shared.
                if let Some(manifest) = pkg.canonical_manifests().next() {
                    let qualified = TagTemplate::default_for(&PackageId::Prefixed {
                        ecosystem: manifest.ecosystem(),
                        name: pkg.id.name().to_string(),
                    });
                    let qualified_last = take_chosen(
                        select_last_tag(&qualified, grammar, all_tags.0.iter().copied()).map_err(GraphError::from)?,
                        &mut diagnostics,
                    );
                    chosen = newest(chosen, qualified_last);
                }
            }
            last.insert(pkg.id.clone(), chosen);
            templates.insert(pkg.id.clone(), tmpl);
            pre_cursor.insert(pkg.id.clone(), None);
        }

        Ok(TagIndex {
            last,
            templates,
            pre_cursor,
            foreign,
            all_tags: all_tags_set,
            commits: std::cell::OnceCell::new(),
            diagnostics,
        })
    }

    pub fn last_tag(&self, id: &PackageId) -> Option<&LastTag> {
        self.last.get(id).and_then(|opt| opt.as_ref())
    }

    pub fn template(&self, id: &PackageId) -> &TagTemplate {
        &self.templates[id]
    }

    pub fn pre_cursor(&self, id: &PackageId) -> Option<&CommitSha> {
        self.pre_cursor.get(id).and_then(|opt| opt.as_ref())
    }

    /// Returns whether `tag_name` is present in the raw tag list fetched
    /// during `build` -- an exact match, not a glob. Lets callers checking
    /// tag existence once per package (e.g. `derive_unreleased_decision`)
    /// consult this in-memory set instead of shelling out to `git` again
    /// for each one.
    pub fn contains_tag(&self, tag_name: &str) -> bool {
        self.all_tags.contains(tag_name)
    }

    /// The commit `tag_name` ends at. Every tag is read in one process the first time, so asking once per package
    /// costs no process each; a tag that ends at something else is left to `git rev-parse`.
    pub fn commit_of(&self, git: &GitAccess<'_>, tag_name: &str) -> Result<Option<CommitSha>, GraphError> {
        if !self.all_tags.contains(tag_name) {
            return Ok(git.resolve_commit(&format!("refs/tags/{tag_name}"))?);
        }
        if self.commits.get().is_none() {
            let commits = git
                .tags_with_commits()?
                .into_iter()
                .filter_map(|(name, commit)| Some((name.as_str().to_owned(), commit?)))
                .collect();
            drop(self.commits.set(commits));
        }
        match self.commits.get().and_then(|commits| commits.get(tag_name)) {
            Some(commit) => Ok(Some(commit.clone())),
            None => Ok(git.resolve_commit(&format!("refs/tags/{tag_name}"))?),
        }
    }

    /// Whether `tag_name` exists and was made by `id`, not by another package that held the same name.
    pub fn is_tag_of(&self, id: &PackageId, tag_name: &str) -> bool {
        self.contains_tag(tag_name) && !self.foreign.get(id).is_some_and(|tags| tags.contains(tag_name))
    }

    /// Constructs an empty `TagIndex` with no packages or tags — useful in
    /// unit tests that do not exercise tag-based logic.
    pub fn empty() -> Self {
        TagIndex {
            last: BTreeMap::new(),
            templates: BTreeMap::new(),
            pre_cursor: BTreeMap::new(),
            foreign: BTreeMap::new(),
            all_tags: std::collections::BTreeSet::new(),
            commits: std::cell::OnceCell::new(),
            diagnostics: Vec::new(),
        }
    }
}

