29	
30	/// Package identity extracted directly from manifest source text via
31	/// [`read_identity`], without going through the full `Manifest::open`
32	/// lifecycle (workspace-inheritance context, on-disk path resolution,
33	/// atomic-write machinery). For callers that already hold a manifest's
34	/// content as a string -- a `git show` blob, a walker's pre-read buffer --
35	/// and only need the package's name and/or where its version comes from.
36	#[derive(Clone, Debug, Default, PartialEq, Eq)]
37	pub struct ManifestIdentity {
38	    pub name: Option<String>,
39	    pub version: Option<VersionSource>,
40	}
41	
42	/// Where a manifest's version declaration comes from. Distinct from a raw
43	/// `Option<String>` so Cargo's `version.workspace = true` is a real,
44	/// distinguishable case instead of being silently collapsed into "no
45	/// version present". [`read_identity`] never resolves the inherited value
46	/// (it has no workspace context); [`read_effective_version`] resolves supplied blobs.
47	#[derive(Clone, Debug, PartialEq, Eq)]
48	pub enum VersionSource {
49	    Literal(String),
50	    InheritedFromWorkspace,
51	}
52	
53	#[derive(Clone, Debug, PartialEq, Eq)]
54	pub struct EffectiveManifestVersion {
55	    pub version: Version,
56	    pub authority: std::path::PathBuf,
57	}
58	
59	/// Reads a manifest's effective version from text the caller already holds. `manifest_at` supplies any other
60	/// workspace-relative manifest by path, or `None` when there is none, so a Cargo `version.workspace = true` resolves
61	/// against the workspace that governs the package at the same revision. `reads` remembers the workspace manifests
62	/// already seen, so reading many packages of one revision parses each once.
63	///
64	/// # Errors
65	///
66	/// The manifest does not parse, declares an invalid version, or inherits one that no governing workspace declares; or
67	/// `manifest_at` fails.
68	pub fn read_effective_version<E: From<ManifestError>>(
69	    format: ManifestFormat,
70	    source: &str,
71	    path: &Path,
72	    reads: &mut WorkspaceReads,
73	    mut manifest_at: impl FnMut(&Path) -> Result<Option<String>, E>,
74	) -> Result<Option<EffectiveManifestVersion>, E> {
75	    let identity = read_identity(format, source, path)?;
76	    let (version, authority) = match identity.version {
77	        Some(VersionSource::Literal(raw)) => {
78	            let version = Version::parse(&raw, format.ecosystem().version_grammar()).map_err(|source| {
79	                ManifestError::InvalidVersion {
80	                    path: path.to_path_buf(),
81	                    raw,
82	                    source,
83	                }
84	            })?;
85	            (version, path.to_path_buf())
86	        }
87	        Some(VersionSource::InheritedFromWorkspace) => {
88	            let missing = |path: &Path| ManifestError::MissingField {
89	                path: path.to_path_buf(),
90	                field: "workspace.package.version",
91	            };
92	            let member = cargo::parse_manifest(path, source)?;
93	            let root_manifest = reads
94	                .enclosing(path, &member, &mut manifest_at)?
95	                .ok_or_else(|| missing(path))?;
96	            let version = reads
97	                .version(&root_manifest, &mut manifest_at)?
98	                .ok_or_else(|| missing(&root_manifest))?;
99	            (version, root_manifest)
100	        }
101	        None => return Ok(None),
102	    };
103	    Ok(Some(EffectiveManifestVersion { version, authority }))
104	}
105	
106	/// Extracts a package's name and version source directly from `source`,
107	/// the raw text of a manifest matching `format`. Pure and I/O-free.
108	///
109	/// Replaces hand-parsing `Cargo.toml`/`package.json`/`pyproject.toml` at
110	/// call sites that already hold manifest content as a string rather than a
111	/// path `open()` can read from disk (audit pattern B) -- e.g. a `git show`
112	/// blob, or a directory-walker's pre-read buffer.
113	///
114	/// `path` is used only to build accurate `ManifestError::Parse` locations
115	/// on a parse failure; it need not exist on disk. Only the three
116	/// canonical-identity formats ([`Ecosystem::CANONICAL`]) are supported --
117	/// any other format returns `Err(ManifestError::ReadOnlyFormat)`.
118	pub fn read_identity(format: ManifestFormat, source: &str, path: &Path) -> Result<ManifestIdentity, ManifestError> {
119	    match format {
120	        ManifestFormat::CargoToml => cargo::identity_from_source(source, path),
121	        ManifestFormat::PackageJson => npm::identity_from_source(source, path),
122	        ManifestFormat::PyprojectToml => python::identity_from_source(source, path),
123	        other => Err(ManifestError::ReadOnlyFormat {
124	            path: path.to_path_buf(),
125	            format: other,
126	            reason: "read_identity only supports the three canonical-identity manifest formats \
127	                     (Cargo.toml, package.json, pyproject.toml)",
128	        }),
129	    }
