234	impl<'a> OpenContext<'a> {
235	    /// Builds an [`OpenContext`] rooted at `root` by resolving Cargo
236	    /// workspace inheritance (when `root/Cargo.toml` exists) and detecting
237	    /// the npm workspace kind. This is the single reusable constructor for
238	    /// the "check Cargo.toml exists, load workspace inheritance, detect npm
239	    /// workspace kind" sequence that call sites previously reimplemented
240	    /// independently (audit pattern: duplication) -- see
241	    /// `callisto-graph`'s `walk`, `lib` (`Workspace::base_versions`),
242	    /// `apply`, and `commands::version` modules.
243	    ///
244	    /// # Errors
245	    ///
246	    /// A root `Cargo.toml` or `package.json` that exists but cannot be read or parsed. An inheriting member
247	    /// could not be opened without it, so a missing context is an error, never an empty one.
248	    pub fn for_workspace_root(root: &'a Path) -> Result<OpenContext<'a>, callisto_model::ManifestError> {
249	        let cargo_manifest = Path::new("Cargo.toml");
250	        let cargo_workspace = if callisto_model::strict_fs::exists(&root.join(cargo_manifest)).map_err(|e| {
251	            callisto_model::ManifestError::Read {
252	                path: cargo_manifest.to_path_buf(),
253	                message: e.to_string(),
254	            }
255	        })? {
256	            Some(Arc::new(
257	                WorkspaceCargoResolver::load_at(root, cargo_manifest)?.inheritance()?,
258	            ))
259	        } else {
260	            None
261	        };
262	
263	        let npm_workspace_kind = detect_npm_workspace_kind(root)?;
264	
265	        Ok(OpenContext {
266	            workspace_root: root,
267	            cargo_workspace,
268	            cargo_roots: CargoRoots::default(),
269	            npm_workspace_kind,
270	        })
271	    }
272	
273	    /// The inheritance a Cargo manifest at `manifest` (workspace-relative, already parsed as `doc`) draws on: that of the
274	    /// Cargo workspace that governs it, which need not be the one at `workspace_root`.
275	    ///
276	    /// # Errors
277	    ///
278	    /// No Cargo workspace governs it, or the one that does cannot be read.
279	    pub(crate) fn cargo_inheritance(
280	        &self,
281	        manifest: &Path,
282	        doc: &toml_edit::DocumentMut,
283	    ) -> Result<Arc<WorkspaceInheritance>, ManifestError> {
284	        let found =
285	            locked(&self.cargo_roots.reads).enclosing(manifest, doc, cargo::read_manifest_text(self.workspace_root))?;
286	        let Some(root_manifest) = found else {
287	            return Err(ManifestError::Read {
288	                path: manifest.to_path_buf(),
289	                message: "declares .workspace = true but no Cargo workspace governs it: no Cargo.toml at or above its \
290	                          directory has a [workspace] table"
291	                    .to_string(),
292	            });
293	        };
294	        if let Some(shared) = self
295	            .cargo_workspace
296	            .as_ref()
297	            .filter(|shared| shared.root_manifest == root_manifest)
298	        {
299	            return Ok(Arc::clone(shared));
300	        }
301	        let mut loaded = locked(&self.cargo_roots.inheritance);
302	        if let Some(known) = loaded.get(&root_manifest) {
303	            return Ok(Arc::clone(known));
304	        }
305	        let inheritance =
306	            Arc::new(WorkspaceCargoResolver::load_at(self.workspace_root, &root_manifest)?.inheritance()?);
307	        loaded.insert(root_manifest, Arc::clone(&inheritance));
308	        Ok(inheritance)
309	    }
310	}
