312	/// Test-observability counter: total number of times [`open`] has been
313	/// invoked. Production code never reads this; it exists so callers (in
314	/// particular, callers building a caching layer on top of `open()`) can
315	/// write regression tests asserting that a given manifest path is opened
316	/// (read + parsed from disk) at most once per logical operation, instead of
317	/// once per call site. See `callisto-graph`'s `manifest_cache` module.
318	static OPEN_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
319	
320	/// Resets the internal manifest-open call counter to zero. Intended for use in test setup.
321	pub fn reset_open_call_count() {
322	    OPEN_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
323	}
324	
325	/// Reads the current value of the internal manifest-open call counter.
326	pub fn open_call_count() -> usize {
327	    OPEN_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
328	}
329	
330	/// Test-observability counter: total number of times a `Manifest`
331	/// implementor's `persist` has returned `Ok`. Production code never reads
332	/// this; it exists so callers can write regression tests asserting a given
333	/// manifest path is flushed to disk at most once per logical operation.
334	/// Distinct from `OPEN_CALL_COUNT` so open-count and persist-count
335	/// assertions in the same test are independent.
336	static PERSIST_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
337	
338	/// Resets the internal manifest-persist call counter to zero. Intended for use in test setup.
339	pub fn reset_persist_call_count() {
340	    PERSIST_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
341	}
342	
343	/// Reads the current value of the internal manifest-persist call counter.
344	pub fn persist_call_count() -> usize {
345	    PERSIST_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
346	}
347	
348	/// Increments PERSIST_CALL_COUNT by one. Called by each Manifest
349	/// implementor's persist() immediately after its own atomic_write returns
350	/// Ok; PERSIST_CALL_COUNT itself is private to this module, so this is the
351	/// only way other modules in this crate may increment it.
352	pub(crate) fn record_persist_call() {
353	    PERSIST_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
354	}
355	
356	/// Test-observability counter: total number of times
357	/// [`cargo::WorkspaceCargoResolver::load`] has been invoked. Deliberately
358	/// NOT folded into `OPEN_CALL_COUNT`: `OpenContext::for_workspace_root`
359	/// calls `WorkspaceCargoResolver::load` unconditionally whenever the
360	/// workspace root has a `Cargo.toml`, regardless of whether that plan
361	/// touches any workspace-inherited field -- merging the two counters would
362	/// make nearly every existing `open_call_count()` assertion in this crate
363	/// (and `callisto-graph`) spuriously count an unrelated resolver load.
364	/// Production code never reads this.
365	static RESOLVER_LOAD_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
366	
367	/// Resets the internal `WorkspaceCargoResolver::load` call counter to zero. Intended for use in test setup.
368	pub fn reset_resolver_load_call_count() {
369	    RESOLVER_LOAD_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
370	}
371	
372	/// Reads the current value of the internal `WorkspaceCargoResolver::load` call counter.
373	pub fn resolver_load_call_count() -> usize {
374	    RESOLVER_LOAD_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
375	}
376	
377	/// Increments RESOLVER_LOAD_CALL_COUNT by one. Called at the top of
378	/// `WorkspaceCargoResolver::load`, mirroring where `open()` increments
379	/// `OPEN_CALL_COUNT` -- counts every invocation, including ones that go on
380	/// to fail parsing.
381	pub(crate) fn record_resolver_load_call() {
382	    RESOLVER_LOAD_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
383	}
384	
385	/// Test-observability counter: total number of times
386	/// [`cargo::WorkspaceCargoResolver::persist`] has returned `Ok`. Kept
387	/// separate from `PERSIST_CALL_COUNT` for the same reason
388	/// `RESOLVER_LOAD_CALL_COUNT` is kept separate from `OPEN_CALL_COUNT`:
389	/// `PERSIST_CALL_COUNT` is documented and consumed as scoped exclusively to
390	/// the `Manifest` trait's three implementors. Production code never reads
391	/// this.
392	static RESOLVER_PERSIST_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
393	
394	/// Resets the internal `WorkspaceCargoResolver::persist` call counter to zero. Intended for use in test setup.
395	pub fn reset_resolver_persist_call_count() {
396	    RESOLVER_PERSIST_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
397	}
398	
399	/// Reads the current value of the internal `WorkspaceCargoResolver::persist` call counter.
400	pub fn resolver_persist_call_count() -> usize {
