411	/// Opens a manifest file matching `decl.format`.
412	pub fn open(decl: &ManifestDecl, ctx: &OpenContext<'_>) -> Result<Box<dyn Manifest>, ManifestError> {
413	    OPEN_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
414	    if decl.role == ManifestRole::Lockfile {
415	        return Err(ManifestError::ReadOnlyFormat {
416	            path: decl.path.clone(),
417	            format: decl.format,
418	            reason: "lockfiles are regenerated via subprocess, never opened as a Manifest handle",
419	        });
420	    }
421	
422	    match decl.format {
423	        ManifestFormat::CargoToml => Ok(Box::new(CargoToml::open(decl, ctx)?)),
424	        ManifestFormat::PackageJson => Ok(Box::new(PackageJson::open(decl, ctx)?)),
425	        ManifestFormat::PyprojectToml => Ok(Box::new(PyprojectToml::open(decl, ctx)?)),
426	        other => Err(ManifestError::ReadOnlyFormat {
427	            path: decl.path.clone(),
428	            format: other,
429	            reason: "not implemented yet",
430	        }),
431	    }
432	}
