//! Per-ecosystem manifest read/write for callisto.

use std::path::Path;
use std::sync::Arc;

use callisto_model::{
    ApplyPermit, DepSpec, Ecosystem, ManifestDecl, ManifestError, ManifestFormat, ManifestRole, Version, WorkspaceKind,
};

pub mod atomic;

pub mod cargo;
mod common;
mod json_text;
pub mod npm;
pub mod python;

pub use cargo::{
    cargo_package_name, cargo_workspace_of, declares_workspace, enclosing_workspace_manifest,
    missing_crates_io_metadata, named_workspace_manifest, parse_manifest, read_manifest_text,
    workspace_manifest_candidates, CargoToml, InheritedDep, WorkspaceCargoResolver, WorkspaceInheritance,
    WorkspaceReads,
};
pub use npm::{
    detect_npm_workspace_kind, napi_binary_name, npm_declares_private, npm_package_name, npm_role_from_source,
    read_napi_targets, PackageJson,
};
pub use python::{python_package_name, PyprojectToml, Requirement};

/// Package identity extracted directly from manifest source text via
/// [`read_identity`], without going through the full `Manifest::open`
/// lifecycle (workspace-inheritance context, on-disk path resolution,
/// atomic-write machinery). For callers that already hold a manifest's
/// content as a string -- a `git show` blob, a walker's pre-read buffer --
/// and only need the package's name and/or where its version comes from.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ManifestIdentity {
    pub name: Option<String>,
    pub version: Option<VersionSource>,
}

/// Where a manifest's version declaration comes from. Distinct from a raw
/// `Option<String>` so Cargo's `version.workspace = true` is a real,
/// distinguishable case instead of being silently collapsed into "no
/// version present". [`read_identity`] never resolves the inherited value
/// (it has no workspace context); [`read_effective_version`] resolves supplied blobs.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum VersionSource {
    Literal(String),
    InheritedFromWorkspace,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct EffectiveManifestVersion {
    pub version: Version,
    pub authority: std::path::PathBuf,
}

/// Reads a manifest's effective version from text the caller already holds. `manifest_at` supplies any other
/// workspace-relative manifest by path, or `None` when there is none, so a Cargo `version.workspace = true` resolves
/// against the workspace that governs the package at the same revision. `reads` remembers the workspace manifests
/// already seen, so reading many packages of one revision parses each once.
///
/// # Errors
///
/// The manifest does not parse, declares an invalid version, or inherits one that no governing workspace declares; or
/// `manifest_at` fails.
pub fn read_effective_version<E: From<ManifestError>>(
    format: ManifestFormat,
    source: &str,
    path: &Path,
    reads: &mut WorkspaceReads,
    mut manifest_at: impl FnMut(&Path) -> Result<Option<String>, E>,
) -> Result<Option<EffectiveManifestVersion>, E> {
    let identity = read_identity(format, source, path)?;
    let (version, authority) = match identity.version {
        Some(VersionSource::Literal(raw)) => {
            let version = Version::parse(&raw, format.ecosystem().version_grammar()).map_err(|source| {
                ManifestError::InvalidVersion {
                    path: path.to_path_buf(),
                    raw,
                    source,
                }
            })?;
            (version, path.to_path_buf())
        }
        Some(VersionSource::InheritedFromWorkspace) => {
            let missing = |path: &Path| ManifestError::MissingField {
                path: path.to_path_buf(),
                field: "workspace.package.version",
            };
            let member = cargo::parse_manifest(path, source)?;
            let root_manifest = reads
                .enclosing(path, &member, &mut manifest_at)?
                .ok_or_else(|| missing(path))?;
            let version = reads
                .version(&root_manifest, &mut manifest_at)?
                .ok_or_else(|| missing(&root_manifest))?;
            (version, root_manifest)
        }
        None => return Ok(None),
    };
    Ok(Some(EffectiveManifestVersion { version, authority }))
}

/// Extracts a package's name and version source directly from `source`,
/// the raw text of a manifest matching `format`. Pure and I/O-free.
///
/// Replaces hand-parsing `Cargo.toml`/`package.json`/`pyproject.toml` at
/// call sites that already hold manifest content as a string rather than a
/// path `open()` can read from disk (audit pattern B) -- e.g. a `git show`
/// blob, or a directory-walker's pre-read buffer.
///
/// `path` is used only to build accurate `ManifestError::Parse` locations
/// on a parse failure; it need not exist on disk. Only the three
/// canonical-identity formats ([`Ecosystem::CANONICAL`]) are supported --
/// any other format returns `Err(ManifestError::ReadOnlyFormat)`.
pub fn read_identity(format: ManifestFormat, source: &str, path: &Path) -> Result<ManifestIdentity, ManifestError> {
    match format {
        ManifestFormat::CargoToml => cargo::identity_from_source(source, path),
        ManifestFormat::PackageJson => npm::identity_from_source(source, path),
        ManifestFormat::PyprojectToml => python::identity_from_source(source, path),
        other => Err(ManifestError::ReadOnlyFormat {
            path: path.to_path_buf(),
            format: other,
            reason: "read_identity only supports the three canonical-identity manifest formats \
                     (Cargo.toml, package.json, pyproject.toml)",
        }),
    }
}

/// The role an npm `package.json` manifest's own content declares itself to
/// play (e.g. a napi-rs platform package, signaled by `os`+`cpu` constraint
/// arrays), detected directly from the manifest's already-parsed document.
///
/// Distinct from [`ManifestRole`], which reflects the role a [`ManifestDecl`]
/// was *opened with* (assigned externally by the caller), not what the
/// manifest content itself declares. [`Manifest::npm_role`] lets a caller
/// holding an already-open handle (e.g. from a shared cache) recover this
/// without a second read of the underlying file.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum NpmRole {
    Platform {
        platform: String,
        arch: String,
        abi: Option<String>,
    },
}

/// Trait implemented by per-ecosystem manifest editors.
pub trait Manifest: Send + Sync {
    fn path(&self) -> &Path;
    fn ecosystem(&self) -> Ecosystem;
    fn role(&self) -> ManifestRole;
    fn package_name(&self) -> Result<String, ManifestError>;
    fn current_version(&self) -> Result<Version, ManifestError>;
    fn write_version(&mut self, v: &Version, permit: &ApplyPermit) -> Result<(), ManifestError>;
    fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError>;
    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = callisto_model::DependencyEntry> + '_>;
    fn update_dependency_spec(
        &mut self,
        name: &str,
        kind: callisto_model::DepKind,
        at: &callisto_model::DepLocator,
        new: DepSpec,
        permit: &ApplyPermit,
    ) -> Result<(), ManifestError>;
    fn is_publishable(&self) -> bool {
        true
    }
    fn publish_targets(&self) -> Vec<callisto_model::PublishTarget> {
        if !self.is_publishable() {
            return vec![callisto_model::PublishTarget::None];
        }
        match self.ecosystem() {
            Ecosystem::Cargo => vec![callisto_model::PublishTarget::CratesIo],
            Ecosystem::Npm => vec![callisto_model::PublishTarget::Npm {
                registry: None,
                access: None,
            }],
            _ => vec![callisto_model::PublishTarget::None],
        }
    }
    fn update_optional_dependencies(
        &mut self,
        updates: &[(String, Version)],
        permit: &ApplyPermit,
    ) -> Result<(), ManifestError>;
    /// The role this manifest's own content declares itself to play (see
    /// [`NpmRole`]). `None` for every ecosystem other than npm, and for an
    /// npm manifest that isn't a platform package. Overridden by
    /// `PackageJson`, whose implementation derives this from the document
    /// already parsed at `open()` time -- no second disk read required.
    fn npm_role(&self) -> Option<NpmRole> {
        None
    }
    /// Executable names this package builds; empty for a library-only package.
    fn bin_names(&self) -> Result<Vec<String>, ManifestError> {
        Ok(Vec::new())
    }
    /// The lib name of a napi-rs addon crate: a `cdylib` depending on `napi`.
    fn napi_lib_name(&self) -> Option<String> {
        None
    }
    /// The workspace-level declaration that a `{ workspace = true }` dependency named `name` inherits. `None` for every
    /// ecosystem other than Cargo, and for a manifest that does not inherit it.
    fn inherited_dependency(&self, _name: &str) -> Option<InheritedDep<'_>> {
        None
    }
}

/// Context passed to open() to supply workspace-wide inheritance facts.
pub struct OpenContext<'a> {
    pub workspace_root: &'a Path,
    /// The inheritance of the Cargo workspace rooted at `workspace_root`, loaded once and shared by its members.
    /// A manifest governed by another Cargo workspace loads that workspace's own.
    pub cargo_workspace: Option<Arc<WorkspaceInheritance>>,
    /// The other Cargo workspaces met while opening manifests.
    pub cargo_roots: CargoRoots,
    pub npm_workspace_kind: Option<WorkspaceKind>,
}

/// Cargo workspaces met while opening manifests, remembered so each is read once however many members inherit from it.
#[derive(Default)]
pub struct CargoRoots {
    reads: std::sync::Mutex<WorkspaceReads>,
    inheritance: std::sync::Mutex<std::collections::BTreeMap<std::path::PathBuf, Arc<WorkspaceInheritance>>>,
}

fn locked<T>(mutex: &std::sync::Mutex<T>) -> std::sync::MutexGuard<'_, T> {
    mutex.lock().unwrap_or_else(std::sync::PoisonError::into_inner)
}

impl<'a> OpenContext<'a> {
    /// Builds an [`OpenContext`] rooted at `root` by resolving Cargo
    /// workspace inheritance (when `root/Cargo.toml` exists) and detecting
    /// the npm workspace kind. This is the single reusable constructor for
    /// the "check Cargo.toml exists, load workspace inheritance, detect npm
    /// workspace kind" sequence that call sites previously reimplemented
    /// independently (audit pattern: duplication) -- see
    /// `callisto-graph`'s `walk`, `lib` (`Workspace::base_versions`),
    /// `apply`, and `commands::version` modules.
    ///
    /// # Errors
    ///
    /// A root `Cargo.toml` or `package.json` that exists but cannot be read or parsed. An inheriting member
    /// could not be opened without it, so a missing context is an error, never an empty one.
    pub fn for_workspace_root(root: &'a Path) -> Result<OpenContext<'a>, callisto_model::ManifestError> {
        let cargo_manifest = Path::new("Cargo.toml");
        let cargo_workspace = if callisto_model::strict_fs::exists(&root.join(cargo_manifest)).map_err(|e| {
            callisto_model::ManifestError::Read {
                path: cargo_manifest.to_path_buf(),
                message: e.to_string(),
            }
        })? {
            Some(Arc::new(
                WorkspaceCargoResolver::load_at(root, cargo_manifest)?.inheritance()?,
            ))
        } else {
            None
        };

        let npm_workspace_kind = detect_npm_workspace_kind(root)?;

        Ok(OpenContext {
            workspace_root: root,
            cargo_workspace,
            cargo_roots: CargoRoots::default(),
            npm_workspace_kind,
        })
    }

    /// The inheritance a Cargo manifest at `manifest` (workspace-relative, already parsed as `doc`) draws on: that of the
    /// Cargo workspace that governs it, which need not be the one at `workspace_root`.
    ///
    /// # Errors
    ///
    /// No Cargo workspace governs it, or the one that does cannot be read.
    pub(crate) fn cargo_inheritance(
        &self,
        manifest: &Path,
        doc: &toml_edit::DocumentMut,
    ) -> Result<Arc<WorkspaceInheritance>, ManifestError> {
        let found =
            locked(&self.cargo_roots.reads).enclosing(manifest, doc, cargo::read_manifest_text(self.workspace_root))?;
        let Some(root_manifest) = found else {
            return Err(ManifestError::Read {
                path: manifest.to_path_buf(),
                message: "declares .workspace = true but no Cargo workspace governs it: no Cargo.toml at or above its \
                          directory has a [workspace] table"
                    .to_string(),
            });
        };
        if let Some(shared) = self
            .cargo_workspace
            .as_ref()
            .filter(|shared| shared.root_manifest == root_manifest)
        {
            return Ok(Arc::clone(shared));
        }
        let mut loaded = locked(&self.cargo_roots.inheritance);
        if let Some(known) = loaded.get(&root_manifest) {
            return Ok(Arc::clone(known));
        }
        let inheritance =
            Arc::new(WorkspaceCargoResolver::load_at(self.workspace_root, &root_manifest)?.inheritance()?);
        loaded.insert(root_manifest, Arc::clone(&inheritance));
        Ok(inheritance)
    }
}

/// Test-observability counter: total number of times [`open`] has been
/// invoked. Production code never reads this; it exists so callers (in
/// particular, callers building a caching layer on top of `open()`) can
/// write regression tests asserting that a given manifest path is opened
/// (read + parsed from disk) at most once per logical operation, instead of
/// once per call site. See `callisto-graph`'s `manifest_cache` module.
static OPEN_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// Resets the internal manifest-open call counter to zero. Intended for use in test setup.
pub fn reset_open_call_count() {
    OPEN_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
}

/// Reads the current value of the internal manifest-open call counter.
pub fn open_call_count() -> usize {
    OPEN_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
}

/// Test-observability counter: total number of times a `Manifest`
/// implementor's `persist` has returned `Ok`. Production code never reads
/// this; it exists so callers can write regression tests asserting a given
/// manifest path is flushed to disk at most once per logical operation.
/// Distinct from `OPEN_CALL_COUNT` so open-count and persist-count
/// assertions in the same test are independent.
static PERSIST_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// Resets the internal manifest-persist call counter to zero. Intended for use in test setup.
pub fn reset_persist_call_count() {
    PERSIST_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
}

/// Reads the current value of the internal manifest-persist call counter.
pub fn persist_call_count() -> usize {
    PERSIST_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
}

/// Increments PERSIST_CALL_COUNT by one. Called by each Manifest
/// implementor's persist() immediately after its own atomic_write returns
/// Ok; PERSIST_CALL_COUNT itself is private to this module, so this is the
/// only way other modules in this crate may increment it.
pub(crate) fn record_persist_call() {
    PERSIST_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
}

/// Test-observability counter: total number of times
/// [`cargo::WorkspaceCargoResolver::load`] has been invoked. Deliberately
/// NOT folded into `OPEN_CALL_COUNT`: `OpenContext::for_workspace_root`
/// calls `WorkspaceCargoResolver::load` unconditionally whenever the
/// workspace root has a `Cargo.toml`, regardless of whether that plan
/// touches any workspace-inherited field -- merging the two counters would
/// make nearly every existing `open_call_count()` assertion in this crate
/// (and `callisto-graph`) spuriously count an unrelated resolver load.
/// Production code never reads this.
static RESOLVER_LOAD_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// Resets the internal `WorkspaceCargoResolver::load` call counter to zero. Intended for use in test setup.
pub fn reset_resolver_load_call_count() {
    RESOLVER_LOAD_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
}

/// Reads the current value of the internal `WorkspaceCargoResolver::load` call counter.
pub fn resolver_load_call_count() -> usize {
    RESOLVER_LOAD_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
}

/// Increments RESOLVER_LOAD_CALL_COUNT by one. Called at the top of
/// `WorkspaceCargoResolver::load`, mirroring where `open()` increments
/// `OPEN_CALL_COUNT` -- counts every invocation, including ones that go on
/// to fail parsing.
pub(crate) fn record_resolver_load_call() {
    RESOLVER_LOAD_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
}

/// Test-observability counter: total number of times
/// [`cargo::WorkspaceCargoResolver::persist`] has returned `Ok`. Kept
/// separate from `PERSIST_CALL_COUNT` for the same reason
/// `RESOLVER_LOAD_CALL_COUNT` is kept separate from `OPEN_CALL_COUNT`:
/// `PERSIST_CALL_COUNT` is documented and consumed as scoped exclusively to
/// the `Manifest` trait's three implementors. Production code never reads
/// this.
static RESOLVER_PERSIST_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// Resets the internal `WorkspaceCargoResolver::persist` call counter to zero. Intended for use in test setup.
pub fn reset_resolver_persist_call_count() {
    RESOLVER_PERSIST_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
}

/// Reads the current value of the internal `WorkspaceCargoResolver::persist` call counter.
pub fn resolver_persist_call_count() -> usize {
    RESOLVER_PERSIST_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
}

/// Increments RESOLVER_PERSIST_CALL_COUNT by one. Called by
/// `WorkspaceCargoResolver::persist` immediately after its own
/// `atomic_write` returns `Ok`.
pub(crate) fn record_resolver_persist_call() {
    RESOLVER_PERSIST_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
}

/// Opens a manifest file matching `decl.format`.
pub fn open(decl: &ManifestDecl, ctx: &OpenContext<'_>) -> Result<Box<dyn Manifest>, ManifestError> {
    OPEN_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    if decl.role == ManifestRole::Lockfile {
        return Err(ManifestError::ReadOnlyFormat {
            path: decl.path.clone(),
            format: decl.format,
            reason: "lockfiles are regenerated via subprocess, never opened as a Manifest handle",
        });
    }

    match decl.format {
        ManifestFormat::CargoToml => Ok(Box::new(CargoToml::open(decl, ctx)?)),
        ManifestFormat::PackageJson => Ok(Box::new(PackageJson::open(decl, ctx)?)),
        ManifestFormat::PyprojectToml => Ok(Box::new(PyprojectToml::open(decl, ctx)?)),
        other => Err(ManifestError::ReadOnlyFormat {
            path: decl.path.clone(),
            format: other,
            reason: "not implemented yet",
        }),
    }
}

/// Dispatches spec round-trip rewriting to the appropriate ecosystem handler.
pub fn round_trip(ecosystem: Ecosystem, spec: &DepSpec, target: &Version) -> Option<DepSpec> {
    match (ecosystem, spec) {
        (Ecosystem::Cargo, _) => cargo::round_trip(spec, target),
        (Ecosystem::Npm, _) => npm::round_trip(spec, target),
        (Ecosystem::Pypi, _) => python::round_trip(spec, target),
        _ => None,
    }
}

